import{c as e}from"./DQIURQBV.js";const i={lang:"de",meta:{title:`${e.brand} — ein KI-Experte für Unternehmen und für Einzelpersonen`,description:`${e.brand} ist ein Berliner Unternehmen, das Ihnen einen erfahrenen KI-Experten an die Seite stellt. Für Unternehmen: Beratung im Haus, das Team befähigt, die Plattformen gebaut — jede Entscheidung bleibt bei Ihrer Führung. Für Einzelpersonen: eine klare Antwort darauf, was KI für Ihre Entscheidung, Ihre Idee oder Ihre Fähigkeiten tun kann, und Hilfe, sie selbst zu nutzen. Das Erstgespräch ist kostenlos.`},nav:{contact:"Kontakt",menu:"Menü",sections:["Für wen","Wie wir arbeiten","Beispiele","Wer wir sind","Kontakt"],theme:"Farbschema wechseln",themeLight:"Hell",themeDark:"Dunkel"},hero:{headline:"Ein KI-Experte an Ihrer Seite.",subline:`${e.brand} setzt einen erfahrenen KI-Experten an den Tisch der Menschen, die einen brauchen. Für ein Unternehmen, ein Team oder eine Forschungsgruppe heißt das: finden, wo KI verändert, was Sie können, es im eigenen Betrieb beweisen und es führen, solange es sich lohnt. Für eine einzelne Person heißt es: eine klare Antwort zu Ihrer Entscheidung, Ihrer Idee oder Ihren Fähigkeiten, und Hilfe, KI selbst zu nutzen. So oder so bleibt jede Entscheidung bei Ihnen.`,button:"30-Minuten-Gespräch vereinbaren"},doors:{eyebrow:"Für wen wir arbeiten",title:"Zwei Türen. Eine Arbeitsweise.",business:{label:"Für Unternehmen",title:"Sie führen etwas.",text:"Ein Unternehmen, ein Start-up, eine Abteilung, ein Büro, eine Forschungsgruppe — alles, in dem Menschen arbeiten und jemand entscheidet. Sie sehen, dass KI Ihre Branche verändert, Sie haben keinen Platz für eine KI-Abteilung, und Sie wollen eine klare Antwort, was sie für Sie tut. Wir werden Ihr KI-Experte: zuerst die Beratung, dann die Rolle Head of AI, solange es sich lohnt.",cta:"So arbeiten wir mit Unternehmen"},individual:{label:"Für Einzelpersonen",title:"Sie sind eine Person mit einer Frage.",text:"Man braucht kein Unternehmen, um einen KI-Experten zu brauchen. Eine Entscheidung, in der viel Geld steckt, ein Unternehmen, das Sie gründen wollen, eine Idee, die Sie noch nicht einschätzen können, eine Fähigkeit, die Sie lernen wollen, ein Kind, das mit all dem aufwachsen wird. Sie bringen die Frage; wir bringen, was KI dazu kann und nicht kann, in klarer Sprache, und helfen Ihnen, sie selbst zu nutzen.",cta:"So arbeiten wir mit Einzelpersonen"}},agents:{eyebrow:"Was wir tun",title:"KI, die arbeitet, wenn niemand zusieht.",lede:"Die meisten Häuser begegnen KI als Chatfenster, das jemand aufmacht, wenn er daran denkt. Das ist die kleinste Version davon. Was wir bauen, arbeitet von selbst, an Ihrem eigenen Material, für alle, deren Arbeit es berührt — und die erste Aufgabe ist, zu finden, wo sich das in Ihrem Unternehmen lohnt.",items:[{title:"Es läuft im Hintergrund.",text:"Kein Werkzeug, an das Ihre Leute denken müssen. Arbeit, die früher darauf wartete, dass jemand eine freie Stunde hat, läuft durchgehend, auf Ihren eigenen Systemen, und das Ergebnis liegt bereit, wenn Ihr Team kommt."},{title:"Es dient dem ganzen Team, nicht einer Person.",text:"Ein System, genutzt von allen, deren Arbeit dasselbe Material berührt. Was eine Person darüber herausfindet, wie man es benutzt, bekommen alle. Das ist der Unterschied zwischen Lizenzen kaufen und eine Fähigkeit haben."},{title:"Es prüft, wofür Sie keine Zeit haben.",text:"Die Version der Frage, die Sie stellen würden, wenn Sie eine Woche übrig hätten: der Markt, den niemand angesehen hat, die sieben Angebote, die niemand verglichen hat, die Möglichkeit, die nie auf dem Tisch lag. Sie bekommen die Optionen und die Begründung dazu. Entscheiden tun Sie."},{title:"Es verändert, was Sie verkaufen können, nicht nur, was Sie fertig bekommen.",text:"Ein Teil von dem, was wir finden, macht eine bestehende Woche kürzer. Ein Teil wird eine Leistung, die Sie letztes Jahr nicht anbieten konnten. Wir testen beides in Ihrem eigenen Betrieb, mit Ihren eigenen Daten, bevor Sie sich für eines entscheiden."}]},studio:{worksLabel:"Beispiele aus der Praxis",capabilitiesLabel:"So arbeiten wir",bookLabel:"Gespräch vereinbaren",bookTitle:"Wählen Sie eine Zeit, die Ihnen passt.",bookNote:"Dreißig Minuten, kostenlos, keine Vorbereitung nötig.",workBack:"Alle Beispiele",worksHeading:"Was KI in Teams wie Ihrem schon erledigt.",worksIntro:"Jedes Beispiel hier haben wir selbst entworfen und betrieben, in einem echten Unternehmen oder Team mit echten Fristen. Jedes zeigt, was sich verändert hat, was bei den Menschen geblieben ist und wo wir die Grenze gezogen haben. Wählen Sie das, was Ihrer Arbeit am nächsten kommt.",worksMeta:`Echte Beispiele für KI in Unternehmen, Start-ups und Forschungsgruppen: Start-ups, Fachbereiche, Forschungsgruppen, Architekturbüros, Kanzleien, Marketingagenturen, Immobilien und gemeinnützige Organisationen. Eingerichtet von ${e.brand}, KI-Beratung in Berlin.`,workName:"Für wen",workCovers:"Was es übernimmt",workMachinery:"Was das System übernimmt",workJudgement:"Was bei Ihnen bleibt",workBuilds:"Was wir bauen",workStops:"Wo es aufhört",workProof:"Woran Sie den Erfolg sehen",workRefuse:"Wann wir Nein sagen",workCost:"Was es von Ihnen verlangt",bookCta:"Oder schreiben Sie uns",close:"Schließen"},who:{rosterTitle:"Wo wir schon gearbeitet haben.",roster:{executives:"Gründer & Geschäftsführung","team-leaders":"Bereichsleitung",research:"Forschungsgruppen",architects:"Architektur","marketing-agencies":"Marketingagenturen",lawyers:"Kanzleien","estate-agents":"Immobilien","volunteer-orgs":"Vereine & Non-Profits"},individuals:{"job-seekers":"Jobsuchende",athletes:"Sportlerinnen & Sportler","home-buyers":"Immobilienkäufer",teachers:"Lehrkräfte",coaches:"Coaches & Yogalehrende","online-shoppers":"Online-Käufer"},notListed:"Eine Branche, in der wir noch nie gearbeitet haben? Die Arbeit läuft genauso ab, und Sie hören früh, wenn nicht. Fragen Sie uns."},method:{label:"Wie wir entscheiden, was wir bauen",title:`Wie wir entscheiden, was wir bauen — ${e.brand}`,metaDescription:"Eine Frage entscheidet alles: Welcher Teil Ihrer Woche ist Routinearbeit, und welcher braucht Ihr Urteil? Die vier Tests, die vier Schritte jedes Projekts und die fünf Gründe, aus denen wir Nein sagen.",headline:"Welcher Teil Ihrer Woche wiederholt sich, und welcher braucht Sie?",intro:["Jeder Mensch, mit dem wir gearbeitet haben, kam mit einer anderen Berufsbezeichnung und demselben Satz: Ein Teil meiner Woche ist unerträglich geworden. Der Beruf wechselt. Die Form des Problems fast nie.","Wir fragen nicht, was Sie automatisieren wollen, denn das weiß fast niemand. Sie wissen, was wehtut. Unsere Aufgabe ist, die genaue Grenze zu finden zwischen der Arbeit, die sich wiederholt, und der Arbeit, die Ihr Urteil braucht, und nur auf der Routineseite zu bauen. Diese Grenze zu finden ist der schwere Teil. Das Werkzeug zu bauen ist der leichte."],testsTitle:"Wie wir das eine vom anderen unterscheiden.",machineryLabel:"Routinearbeit — alle vier müssen zutreffen",machinery:["Es wiederholt sich. Öfter als einmal pro Woche, in ungefähr derselben Form.","Es folgt Regeln. Müssten Sie erklären, wie Sie es tun, könnten Sie es, in Sätzen und nicht in Gesten.","Es ist leicht zu prüfen. Ein falsches Ergebnis erkennen Sie in Sekunden.","Ein entdeckter Fehler kostet wenig. Irrt sich das Werkzeug und Sie merken es, verlieren Sie eine Minute, nicht mehr."],judgementLabel:"Ihr Urteil — eines davon genügt",judgement:["Sie haften dafür. Ihr Name, Ihre Zulassung oder Ihre Unterschrift steht darunter.","Ihr Geschmack ist das Produkt. Man bezahlt Sie genau dafür, dass die Sicht Ihre ist.","Die Beziehung ist das Produkt. Eine Patientin, ein Schüler, eine Mandantin, ein Publikum.","Es ist eine echte Entscheidung unter Unsicherheit, kein Nachschlagen mit Zwischenschritten."],seam:"Wir bauen bis an diese Grenze und nie darüber hinaus. Fast jedes gescheiterte KI-Projekt, das wir retten sollten, ist gescheitert, weil jemand über die Grenze hinaus gebaut hat und der Mensch den Ergebnissen still nicht mehr vertraute.",refuseTitle:"Wann wir Nein sagen.",refuseIntro:"Wir sagen laut Nein und behalten die Beziehung. Nein zu sagen ist der Hauptgrund, warum Mandanten uns anderen Inhabern empfehlen.",refuse:[{title:"Es ist zu wenig davon.",text:"Unter etwa einer Stunde pro Woche kostet es mehr, ein Werkzeug am Laufen zu halten, als die Aufgabe selbst."},{title:"Jeder Fall ist anders.",text:"Gleicht kein Fall dem anderen, gibt es nichts Wiederkehrendes zu übernehmen. Es gibt nur Können, und Können ist kein Engpass, den man beseitigt."},{title:"Ein Fehler wäre zu teuer.",text:"Könnte ein einziges falsches Ergebnis eine Laufbahn beenden, bereitet das Werkzeug das Material vor und tut sonst nichts."},{title:"Ein einfaches Werkzeug gibt es schon.",text:"Ein Kalender, ein Formular, eine geteilte Tabelle, eine Vorlage. Das richten wir ein, sagen es Ihnen und gehen weiter."},{title:"Es ist eine Entscheidung, keine Arbeitslast.",text:"Manche brauchen kein System. Sie müssen etwas entscheiden, das sie vor sich herschieben. Keine Software behebt das."}],registersTitle:"Zwei Arten von Erfahrung.",registersText:`Zwei Register, mit Absicht. Jahre professionelles Engineering hinter uns, im Bau von Produktions-KI-Systemen in großen Organisationen, auf die sich andere Menschen verlassen — diese Arbeit lehrt uns, was Prüfungen, Übergaben und Kollegen übersteht, die nie nach dem Werkzeug gefragt haben. Und bei ${e.brand} sitzen wir am Tisch eines inhabergeführten Hauses oder einer Forschungsgruppe, was uns direkt hält: ein Raum, eine Entscheiderin, kein Gremium.`,casesCta:"Die Beispiele ansehen",teamCta:"So kommen wir in Ihr Team"},built:{items:[{slug:"lawyers",title:`KI für Anwälte: die eigenen Positionen, angewandt auf jeden Entwurf — ${e.brand}`,metaDescription:"Jeder Vertrag, den die Kanzlei angefasst hat, als ein aktuelles Objekt. Jede Frist, die in diesen Verträgen steckt, im Kalender. Und jeder eingehende Entwurf gemessen an den Positionen, die die Kanzlei wirklich hält. Kein „Alle übernehmen“.",label:"Anwälte",headline:"Die eigenen Positionen der Kanzlei, angewandt auf jeden Entwurf, der ankommt.",story:["Eine Wirtschaftskanzlei mit zwei Partnern. Eine Rechtsabteilung mit fünf Personen. Drei Einzelanwälte. Eine Syndika, die die gesamte Rechtsfunktion eines 300-Personen-Unternehmens ist. Im Recht sind sie nicht im Rückstand. Im Rückstand sind sie bei Verträgen als Dateien — die ankommen, wandern, sich ändern und verloren gehen.","Ein Vertrag kommt als Anhang namens Vertrag_final_final_v3(2).docx. Jemand antwortet mit Änderungsverfolgung aus einer Fassung, die längst überholt war. Drei Wochen später verstreicht unbemerkt eine Frist, die nur in diesem Dokument stand. Niemand kann sagen, welche Fassung unterschrieben wurde. Die Juristin verbringt den Abend mit Archivarbeit — mit zwei Staatsexamen."],machinery:["Jeden Vertrag, den die Kanzlei angefasst hat, als ein aktuelles Objekt halten — jede Fassung, jede Gegenseite, jeden Vorgänger, dauerhaft","Die Angaben herausziehen, an denen das Risiko hängt: Parteien, Daten, Laufzeit, Kündigungsfristen, Rechtswahl, Haftungsgrenzen, Verlängerung — jede mit Verweis auf die Seite, aus der sie kommt","Der Fristenkalender — jedes Datum, das in einem Vertrag steckt, sichtbar bevor es zählt","Jeden eingehenden Entwurf an den Positionen messen, die die Kanzlei wirklich hält, und jede Abweichung mit ihrer Begründung markieren","Die Verhandlung in Bewegung halten: wer einen Entwurf schuldet, wer eine Unterschrift schuldet, und wie lange das schon liegt","„Wo ist dieser Vertrag, welche Fassung gilt, und was haben wir vereinbart?“ sofort beantworten, für jeden in der Kanzlei"],judgement:["Ob eine Klausel akzeptabel ist","Was zugestanden wird","Beratung","Unterschrift"],builds:[{name:"Der Vertragsbestand",text:"Ein Ort, an dem jeder Vertrag, den die Kanzlei angefasst hat, als aktuelles Objekt existiert und nicht als Datei, von der jemand eine Kopie hat: erkannt, versioniert, mit Akte und Vorgängerfassung verknüpft, egal woher er kam. Das final_final_v3(2)-Problem verschwindet in Woche eins, und das ist die Veränderung, die zuerst auffällt."},{name:"Das Vertragsdatenblatt",text:"Ein strukturierter Datensatz pro Vertrag. Jedes Feld trägt einen Verweis auf genau die Seite und den Absatz, aus dem es stammt. Nichts wird ohne Fundstelle behauptet, denn eine Angabe, die Sie nicht prüfen können, ist schlimmer als keine — sie sieht aus wie Wissen."},{name:"Der Playbook-Abgleich",text:"Die Positionen der Kanzlei, einmal richtig aufgeschrieben. Das ist die härteste und wertvollste Woche des Projekts, weil die meisten Kanzleien ihre nie aufgeschrieben haben. Danach wird jeder eingehende Entwurf dagegen markiert."},{name:"Die erste Durchsicht",text:"Das Herz des Systems. Ein Word-Dokument mit Änderungsverfolgung, in dem jeder einzelne Vorschlag seine Begründung als Kommentar trägt: aus welcher Playbook-Position er kommt oder welches Risiko er adressiert. Sie öffnen es in Word — Ihrem eigenen Werkzeug, nicht unserem — und nehmen jeden Vorschlag von Hand an oder verwerfen ihn."},{name:"Der Fristenkalender",text:"Jedes Datum landet in Ihrem Kalender, mit Erinnerungen, die näher am Termin eindringlicher werden. Das Stück mit dem höchsten Rohwert, denn eine versäumte Kündigungsfrist ist ein Haftungsfall."}],stops:{title:"Niemals juristische Bewertung, und nichts verlässt ungelesen das Haus.",text:["Keine Beratung, an niemanden, zu keinem Zeitpunkt, intern wie extern. Kein automatischer Versand an die Gegenseite. Keine Klausel wird ohne genannte Begründung umformuliert, die Sie bewerten können. Jede herausgezogene Angabe ist an ihre Fundstelle geheftet, sodass die Prüfung vier Sekunden dauert. Es gibt kein „Alle übernehmen“ — wir wurden gebeten, das zu bauen, und haben abgelehnt.","Dazu die Bedingungen, die es in Deutschland überhaupt einsetzbar machen: ein AV-Vertrag nach Art. 28 DSGVO, dazu eine gesonderte Verschwiegenheitsverpflichtung in Textform nach §43e BRAO mit ausdrücklicher Belehrung über die strafrechtlichen Folgen nach §203 StGB, Datenhaltung in der EU, kein Training auf Mandanteninhalten, gewahrtes Mandatsgeheimnis, ein lückenloses Protokoll jedes Schritts und eine dokumentierte Antwort auf die Kammerfrage „Wer hat das getan, und können Sie es zeigen?“ Ein juristisches KI-System ohne dieses Protokoll ist nicht einsatzfähig, egal was es sonst kann."]},proof:"Versäumte Fristen seit Einführung des Fristenkalenders: bislang keine. „Was haben wir vereinbart, und welche Fassung gilt?“ in Sekunden statt in einem Nachmittag. Der Anteil eingehender Entwürfe, die einen Partner bereits an den Positionen der Kanzlei gemessen erreichen. Und das, was die Partner nennen — Abende, die nicht mehr für Versionsarchäologie draufgehen.",refuse:"Individuelle, hochwertige Einzelverhandlungen. Dort gibt es kein Playbook, weil es keine Wiederholung gibt, und eine erste Durchsicht bei einem wirklich neuartigen Deal ist Rauschen im Gewand der Hilfe.",cost:"Zwei Wochen Ihrer Zeit, um das Playbook mit uns aufzuschreiben — die Positionen, die Ihre Kanzlei tatsächlich vertritt, nicht die, die sie zu vertreten glaubt. Danach etwa elf statt vierzig Minuten pro Vertrag, verbracht mit dem Lesen von Vorschlägen statt mit der Suche nach Fassungen.",quotes:[{text:"Allein das Versionsproblem hat uns Abende gekostet — Vertrag_final_final_v3, und niemand konnte sagen, welcher unterschrieben wurde. Im ersten Monat hat er nur Eingang und Ablage ausgeliefert und dann aufgehört, was ich seltsam fand, bis ich verstand, dass es Absicht war. Die Durchsicht kam später, und jeder einzelne Vorschlag kommt in Word mit einer Begründung an, und ich nehme jeden selbst an oder verwerfe ihn. Er wurde um einen „Alle übernehmen“-Knopf gebeten und hat abgelehnt — hätte er ihn gebaut, hätte ich nicht weiter mit ihm gearbeitet.",name:"Partnerin, Wirtschaftskanzlei"},{text:"Wir sind fünf Menschen und machen die Rechtsarbeit eines Unternehmens mit dreihundert. Meine Woche verändert hat der Fristenkalender — jede Kündigungsfrist in jedem Vertrag ist jetzt ein Termin, von dem ich erfahre; vorher hatten wir einen verpasst, und das war teuer. Die Extraktion heftet jedes Feld an die Seite, von der es stammt, also dauert das Prüfen vier Sekunden statt Vertrauen zu erfordern. Das Audit-Log war für uns nicht verhandelbar, und es war das Erste, wonach er gefragt hat, nicht das Letzte.",name:"Syndika, Industrie, ~300 Beschäftigte"}]},{slug:"architects",title:`KI für Architekten: Protokolle am selben Abend — ${e.brand}`,metaDescription:"Ein Planregister, das den aktuellen Stand kennt, sieben Angebote in einem Vergleich mit markierten Lücken, Baustellenprotokolle am selben Abend. Es entwirft nicht.",label:"Architekten",headline:"Der Papierkram ist am selben Tag erledigt. Entwurf und Konformitätsurteil bleiben bei Ihnen.",story:["Ein Zwei-Personen-Architekturbüro für Wohnungsumbauten, ein Einzelarchitekt vor allem für Bauanträge und Umbauten, und ein mittelgroßes Büro, in dem ein Partner die gesamte Ausschreibung und Vergabe verantwortet. Alle drei haben jahrelang gelernt zu entwerfen, und alle drei verbringen den Großteil ihrer Woche mit dem Papierkram rund um den Entwurf.","Für den einen ist es das Planregister: Welche Revision ging an wen, und hat der Statiker die aktuelle Fassung? Für den nächsten der Angebotsvergleich: sieben Angebote in sieben Formaten, Position für Position über ein Wochenende in Excel. Für den dritten das Baustellenprotokoll: vierzig Fotos, eine Stunde Notizen, und ein Dokument, das noch am selben Abend geschrieben werden muss, sonst wird es gar nicht geschrieben."],machinery:["Jederzeit wissen, welche Revision welchen Plans gilt und wer welche gerade hat","Eine Einreichung gegen die Vollständigkeitsliste der Behörde prüfen, bevor sie das Büro verlässt","Jedes Angebot in eine vergleichbare Tabelle bringen, Position für Position, mit Lücken als Lücken markiert statt als Null gezählt","Was Sie auf der Baustelle gesehen und gesagt haben, in das datierte Protokoll bringen, Fotos referenziert, Fristen herausgezogen","Die offenen Punkte aus jedem Protokoll weitertragen und die Verantwortlichen daran halten","Die maßgebliche Stelle in DIN, LBO, GEG oder Bebauungsplan finden, mit Zitat, nie als Paraphrase","Jede Frist halten, in der das Büro steht: Einwendung, Nachtrag, Gewährleistung"],judgement:["Der Entwurf","Ob eine Lösung baubar und gut ist","Ob ein Angebot glaubwürdig ist, nicht bloß das günstigste","Ob etwas konform ist"],builds:[{name:"Das Planregister",text:"Jeder Plan, jede Revision, wer wann was bekommen hat. Klein und unspektakulär, und es nimmt eine wiederkehrende Sorge weg: „Hat der Statiker Rev C?“ wird zu einer Zwei-Sekunden-Frage mit einer Antwort, die Sie belegen können."},{name:"Der Angebotsvergleich",text:"Sieben PDFs rein, ein Vergleich raus, Position für Position. Nicht bepreiste Positionen werden als Lücke markiert, nicht als Null gezählt. Genau das ist die Falle im Angebotsvergleich: Das billigste Angebot ist sehr oft das, in dem etwas fehlt. Das Werkzeug markiert. Es entscheidet nicht."},{name:"Das Baustellenprotokoll am selben Abend",text:"Auf der Baustelle fotografieren und sprechen Sie. Am Abend liegt das Protokoll vor: datiert, mit Fotobezug, Mängel aufgelistet, Verantwortlichkeiten zugewiesen, Fristen in eine Nachhalteliste übernommen. Das Dokument, das früher um 22 Uhr oder gar nicht entstand, braucht jetzt fünfzehn Minuten Überarbeitung."},{name:"Der Normfinder",text:"Durchsucht Ihre eigene Normenbibliothek und den Bebauungsplan und liefert die Stelle mit Fundstelle. Er schlägt nach. Er gibt eine Norm nie in eigenen Worten wieder, denn eine umformulierte Norm ist ein Haftungsrisiko."},{name:"Die Vollständigkeitsprüfung",text:"Vor der Einreichung, gegen die Liste der Behörde. Sie fängt den fehlenden Nachweis ab, bevor das Bauamt es tut. Das spart Wochen."}],stops:{title:"Keine erzeugten Pläne, und nie der Satz „Das ist konform“.",text:["Keine Massenstudien, keine Grundrissvorschläge. Nicht weil Software nichts Planähnliches erzeugen könnte, sondern weil der Stempel des Architekten Haftung trägt und der Entwurf der gesamte Wert des Büros ist. Ein von Software erzeugter und von einem Menschen unterschriebener Entwurf ist das Schlechteste aus beidem.","Bei der Konformität findet das System die Norm und urteilt nie. Der Satz, den es sagen darf, lautet: „§34 BauGB, Absatz 2, könnte hier greifen — prüfen.“ Der Satz, den es nie sagen darf, lautet: „Das ist konform.“"]},proof:"Protokolle am selben Tag geschrieben: nahe 100%. Stunden pro Angebotsvergleich: Aus einem Wochenende werden etwa zwei Stunden. Wegen Unvollständigkeit zurückgewiesene Einreichungen seit Einführung der Prüfung: bislang keine. Zeit, bis „Welche Revision gilt?“ beantwortet ist.",refuse:"Wenn ein Büro generative Entwurfswerkzeuge will. Das ist ein anderer Beruf als unserer, und für ein Drei-Personen-Büro mit Umbauten löst es ein Problem, das es nicht hat, und bringt eine Haftung mit, die es nicht tragen kann.",cost:"Auf der Baustelle sprechen statt nachts schreiben. Sie fotografieren und diktieren vor Ort, und am Abend überarbeiten Sie das Protokoll fünfzehn Minuten lang, statt es zwei Stunden lang zu schreiben.",quotes:[{text:"Das Protokoll wurde früher um zehn Uhr abends geschrieben oder gar nicht, und „gar nicht“ lag vorn. Ich fotografiere und spreche jetzt vor Ort, und am selben Abend existiert das Dokument, mit Fotobezügen und herausgezogenen Fristen. Fünfzehn Minuten Überarbeiten statt zwei Stunden Schreiben. Er hat unsere Ordnerstruktur übernommen, statt seine eigene aufzudrängen — das klingt klein und hat dazu geführt, dass wir es tatsächlich weiter benutzen.",name:"Architekt, Einzelbüro"},{text:"Der Angebotsvergleich war ein Wochenende. Sieben Angebote in sieben Formaten, von Hand in Excel, und ich hatte immer Angst, etwas zu übersehen. Es normalisiert sie nach Position und markiert nicht bepreiste Positionen als Lücke statt als Null — das ist die eigentliche Falle, denn das billigste Angebot ist meist das, das etwas ausgelassen hat. Es markiert und schließt nicht. Jetzt zwei Stunden, und das Urteil ist weiter meines.",name:"Partner, Architekturbüro, ~14 Beschäftigte"}]},{slug:"team-leaders",title:`KI für Teamleitungen: nichts Beobachtetes geht vergessen — ${e.brand}`,metaDescription:"Alles, was Sie an Ihrem Team wahrnehmen, in einem privaten Protokoll, das Ihnen gehört — damit Feedback konkret ist und eine Beurteilung zusammengesetzt statt erinnert wird. Es bewertet, sortiert und überwacht niemanden.",label:"Teamleitungen",headline:"Es erinnert sich an das, was Sie beobachtet haben. Es bewertet niemanden.",story:["Eine Person führt elf Menschen in einer Engineering-Organisation, eine andere sechs im Kundenservice. Beide wurden befördert, weil sie in dem Job hervorragend waren, den sie jetzt nicht mehr machen, beide haben nie eine Schulung dafür bekommen, und beide ertrinken still in dem Papierkram, den Personalführung mit sich bringt.","Vorbereitung — oder vielmehr ihr Fehlen. Elf Einzelgespräche (1:1) alle zwei Wochen, von denen jedes mit „Letztes Mal sagtest du X, wie ist es gelaufen?“ beginnen sollte und stattdessen damit beginnt, dass die Führungskraft still versucht, sich zu erinnern. Dann das Schreiben: Feedback, das konkret sein muss und dafür Belege braucht, Belege, die irgendwo in der Erinnerung verstreut liegen, und zweimal im Jahr die Beurteilungsrunde, die zwei volle Wochenenden frisst."],machinery:["Alles, was Sie an Ihrem Team wahrgenommen haben, in einem privaten Protokoll halten, das Ihnen gehört: was gesagt, was vereinbart, was noch offen ist","Dafür sorgen, dass jedes Gespräch dort beginnt, wo das letzte endete, statt damit, dass beide versuchen sich zu erinnern","Was Sie beobachtet haben, in Feedback bringen, das konkret genug ist, um anzukommen: Situation, Verhalten, Wirkung","Nachhalten, was Sie delegiert haben und was daraus geworden ist","Zeigen, wohin Ihre Zeit tatsächlich geht, gegen das, wo Sie glauben, dass sie hingeht","Ein Jahr eigener Beobachtungen zusammenstellen, wenn die Beurteilungsrunde kommt, statt sie im November zu rekonstruieren","Festhalten, wie das Team wirklich arbeitet, damit es die nächste Person überlebt, die dazukommt"],judgement:["Die Beurteilung eines Menschen","Was mit jemandem wirklich los ist","Wer befördert wird, wer das schwierige Gespräch bekommt","Die Beziehung, die der ganze Job ist"],builds:[{name:"Das Personenprotokoll",text:"Eine private Datei je Teammitglied, in Ihrer Hand: was die Person zugesagt hat, was daraus geworden ist, und Ihre eigenen Beobachtungen mit Datum. Neunzig Sekunden Diktat nach jedem Einzelgespräch. Das ist das ganze System, und es verändert die Qualität Ihrer Führung stärker als alles andere, was wir bauen — denn konkret zu sein ist der Unterschied zwischen Feedback, das ankommt, und Feedback, das verpufft."},{name:"Jedes Gespräch beginnt, wo das letzte endete",text:"Vor jedem Einzelgespräch: die Vereinbarungen vom letzten Mal, ihr Stand, was noch offen ist, was Sie selbst nachverfolgen wollten. Dreißig Sekunden Lesen ersetzen vier Minuten schlechtes Erinnern — und die Person gegenüber merkt, was von beidem passiert ist."},{name:"Der Feedback-Entwurf",text:"Sie schreiben „Dienstag, das Deployment, gut gelöst“. Zurück kommt ein konkreter Absatz — Situation, Verhalten, Wirkung —, gebaut aus dieser Notiz und sonst nichts. Sie überarbeiten ihn und geben ihn persönlich."},{name:"Wohin Ihre Zeit tatsächlich ging",text:"Einmal im Monat der Unterschied zwischen dem, wo Sie Ihre Woche glauben, und dem, wo sie hinging. Beide Führungskräfte waren erschrocken. Eine stellte fest, dass 8% ihrer Zeit ans Team gingen und 44% an Meetings, deren Teilnahme sie nie hinterfragt hatte."},{name:"Die Beurteilungsmappe",text:"Zur Beurteilungsrunde die Notizen des Jahres je Person, geordnet. Aus zwei Wochenenden wird ein Nachmittag, und die Beurteilungen werden deutlich konkreter, weil sie auf Notizen von damals beruhen statt auf dem, was gerade noch im Kopf ist."}],stops:{title:"Es erzeugt nie eine Bewertung eines Menschen, und niemand wird vom System gemessen.",text:["Es benotet nie, erstellt keine Rangfolge, sagt nicht voraus, wer kündigen könnte, schlägt nie vor, wer zu wenig leistet, und schreibt nie das Fazit einer Beurteilung. Eine von Software erzeugte und von einer Führungskraft unterschriebene Leistungsbeurteilung ist eine Lüge, auf der dann die Laufbahn eines Menschen aufbaut.","Es greift auch nie in die Arbeit der Leute hinein. Kein Zählen von Code-Änderungen, keine Tickets pro Person, keine Analyse von Nachrichten, keine Aktivitätsüberwachung. Beide Führungskräfte hatten Zugang zu Werkzeugen, die das können; wir haben keines empfohlen. Überwachung verändert, was ein Team Ihnen erzählt, lange bevor sie verändert, was es tut — und dann sind Sie blind, ohne es zu merken. Die Personenprotokolle sind Ihre eigenen Notizen über Beschäftigte, also gelten die Betroffenenrechte der DSGVO einschließlich Auskunft: Schreiben Sie nichts, was Sie der Person nicht zeigen würden."]},proof:"Einzelgespräche, die mit einem Nachfassen statt mit einer Leerstelle beginnen: von gelegentlich zu Standard. Zeit für die Beurteilungsrunde. Anteil Ihrer Woche, der tatsächlich beim Team ist. Und ob das Feedback konkret geworden ist, was das Team vor Ihnen merkt.",refuse:"Wenn eine Führungskraft Einblick will, woran ihr Team gerade arbeitet. Das ist ein Vertrauensproblem, und Werkzeuge machen es schlimmer. Wir sagen das offen, und wir haben dieses Gespräch beide Male geführt.",cost:"Neunzig Sekunden Diktat nach jedem Gespräch.",quotes:[{text:"Ich wurde befördert, weil ich in einem Job gut war, den ich nicht mehr mache, und für den neuen hat mich niemand geschult. Neunzig Sekunden Diktat nach jedem 1:1, und jedes Gespräch beginnt jetzt mit „letztes Mal sagtest du X, wie lief das“, statt dass ich still versuche, mich zu erinnern. Mein Team hat es vor mir gemerkt. Die Beurteilungssaison ging von zwei Wochenenden auf einen Nachmittag, und die Beurteilungen sind viel spezifischer, weil sie aus Notizen entstehen, die ich damals geschrieben habe, statt aus dem, was ich im November erinnere.",name:"Engineering-Teamleitung, elf Mitarbeitende"},{text:"Das Kalender-Audit war unangenehm. Acht Prozent meiner Zeit gingen an mein Team und vierundvierzig Prozent an Meetings, deren Teilnahme ich nie hinterfragt hatte. Ich habe gefragt, ob wir Einblick hinzufügen könnten, woran die Leute tatsächlich arbeiten, und er hat nein gesagt und mir erklärt, das sei ein Vertrauensproblem, das Werkzeuge verschlimmern. Das wollte ich nicht hören, und es war das Nützlichste, was mir in dem Jahr jemand gesagt hat.",name:"Leitung Kundenservice, sechs Mitarbeitende"}]},{slug:"estate-agents",title:`KI für Makler: echte Käufer zuerst beantworten — ${e.brand}`,metaDescription:"Jede Anfrage in Minuten beantwortet und nach Qualität sortiert, Exposés mit geprüften Pflichtangaben, Eigentümer wöchentlich informiert. Keine Wertermittlung, keine KI-Fotos.",label:"Immobilienmakler",headline:"Die acht echten Käufer zuerst beantworten, nicht alle neunzig.",story:["Ein selbstständiger Makler in Berlin und ein Zwei-Personen-Büro für Wohnimmobilien mit etwas Vermietung. Sie kamen mit gegensätzlichen Problemen: Der eine ertrank in Anfragen, die er nicht schnell genug beantworten konnte. Das andere schaffte es nicht, Exposés schnell genug fertigzustellen, um den Auftrag zu bekommen.","Ein Angebot geht online, und binnen 48 Stunden kommen 90 Anfragen. Vielleicht acht davon sind qualifizierte Käufer. Der Makler beantwortet sie in der Reihenfolge des Eingangs, um 22 Uhr, schlecht — und hat die Guten schon am ersten Tag verloren. Drumherum: das jedes Mal von vorn gebaute Exposé, der von Hand erstellte Besichtigungsplan und die Nachfassnachrichten nach Besichtigungen, die nie rausgehen."],machinery:["Jede Anfrage in dem Moment qualifizieren, in dem sie ankommt: vollständig, Finanzierung genannt, Anforderungen gegen die Immobilie geprüft","Dafür sorgen, dass kein ernsthafter Käufer wartet — Eingangsbestätigung und Qualifizierungsfragen gehen in Minuten raus, nicht am nächsten Abend","Die ganze Strecke je Objekt halten: wer besichtigt hat, bei wem nachgefasst wurde, wer verstummt ist und wann","Das Exposé aus den eigenen Objektdaten zusammenstellen: Fotos, Grundriss, Energieausweis, Provisionsangabe, Pflichtangaben","Den Eigentümer auf dem Stand halten, ohne dass er fragt, mit Vergleichsangeboten und Vermarktungsdauer","Wissen, welches Ihrer Objekte zäh wird, bevor der Eigentümer anruft und danach fragt"],judgement:["Wertermittlung und Preisstrategie","Welchen Käufer Sie dem Verkäufer empfehlen","Wie Sie einen Eigentümer mit unrealistischer Erwartung beraten","Die Verhandlung"],builds:[{name:"Anfragen sortieren",text:"Jede Anfrage wird binnen Minuten bestätigt, die Qualifizierungsfragen gleich dabei. Die Antworten werden in qualifiziert, unvollständig und ungeeignet einsortiert. Sie kümmern sich dann um acht Menschen statt um neunzig. Die Antwortzeit entscheidet mehr als alles andere darüber, wer den Käufer bekommt — und sie ist reine Routine."},{name:"Kein guter Käufer verliert einen Platz",text:"Qualifizierte Interessenten erreichen Ihre echte Verfügbarkeit ohne eine Runde Nachrichten, und die Plätze, die belegt werden, belegen Leute, die kommen. Die Ausfälle sanken um mehr als die Hälfte. Das zählt, weil ein Ausfall bei einer Sammelbesichtigung einen Platz kostet, den ein echter Käufer wollte."},{name:"Exposé zusammenstellen",text:"Objektdaten rein, rechtssicheres Dokument raus — mit geprüften Pflichtangaben, denn ein fehlender Energieausweiswert ist nach GEG bußgeldbewehrt und genau das, was ein müder Makler am Freitag vergisst. Die Portalfassungen kommen im richtigen Format gleich mit."},{name:"Beschreibung entwerfen",text:"Aus den tatsächlichen Merkmalen, in Ihrer Sprache, ohne erfundene Eigenschaften. Maklertexte haben einen verdienten Ruf, und wir tragen nichts dazu bei — hat das System keine Daten für eine Aussage, macht es die Aussage nicht."},{name:"Wöchentliches Eigentümerupdate",text:"Wöchentlich, automatisch, sachlich: Anfragen, Besichtigungen, Rückmeldungen. Beide Makler sagten, das habe die nervösen Eigentümeranrufe stärker reduziert als alles andere — denn die meisten dieser Anrufe sind die Bitte um Bestätigung, dass nichts ohne sie passiert."}],stops:{title:"Keine Wertermittlung, und nichts, was eine Immobilie falsch darstellt.",text:["In der Wertermittlung stecken Ihr fachliches Urteil und Ihr Ruf, und sie ist die Zahl, um die sich die ganze Beziehung dreht. Das System kann Vergleichsangebote sammeln und Vermarktungsdauern zeigen. Einen Preis nennt es nicht.","Zur Darstellung: keine erzeugten Bilder, kein Wegretuschieren, kein „gemütlich“ für winzig, kein erfundenes Baujahr, keine ausgelassenen Pflichtangaben. Über die Rechtsfolgen hinaus gilt: Alles Erfundene im Exposé fliegt bei der Besichtigung auf — und dann sind Sie die Person, die es geschrieben hat. Das System verhandelt auch nie und spricht mit Käufern nie über den Preis."]},proof:"Minuten bis zur ersten Antwort — von Stunden auf unter fünf. Qualifizierte Interessenten pro Angebot. Ausfallquote bei Besichtigungen. Vermarktungsdauer. Eigentümeranrufe pro Woche, sinkend.",refuse:"Jede Anfrage nach automatischer Wertermittlung oder erzeugten Objektfotos. Ebenso jede Anfrage, Käufern so automatisch zu antworten, dass es nach einem Menschen aussieht. Wenn ein Käufer mit einem System schreibt, soll er das erkennen können.",cost:"Acht gute Anfragen sorgfältig beantworten, statt durch neunzig zu scrollen. Die Objektdaten einmal sauber eintragen, damit Exposé und Beschreibung etwas Wahres haben, aus dem sie entstehen.",quotes:[{text:"Neunzig Anfragen in achtundvierzig Stunden, acht davon echt, und ich habe sie um zehn Uhr abends in Eingangsreihenfolge beantwortet und die Guten am ersten Tag verloren. Jetzt wird alles binnen Minuten bestätigt, mit den Qualifizierungsfragen dabei, und ich richte meine Aufmerksamkeit auf die acht. Die Antwortzeit entscheidet, wer den Käufer bekommt, und sie ist vollständig mechanisch — was er offenbar allen sagt.",name:"Selbstständiger Makler, Berlin"},{text:"Der Exposé-Baukasten prüft die Pflichtangaben, und der fehlende Energieausweiswert am Freitagnachmittag ist genau der Fehler, den ich schon gemacht habe. Er schreibt aus den tatsächlichen Merkmalen der Immobilie und erfindet keine Eigenschaft — was ich angesichts des Rufs meines Berufs für einen Wettbewerbsvorteil halte und nicht für eine Einschränkung. Das wöchentliche Eigentümerupdate hat die nervösen Anrufe stärker reduziert als alles andere.",name:"Zwei-Personen-Agentur, Wohnimmobilien"}]},{slug:"executives",title:`KI für Gründer-CEOs: nichts Wichtiges liegt nur in Ihrem Kopf — ${e.brand}`,metaDescription:"Jede Zusage, jede Beziehung und jede Zahl, auf denen das Unternehmen läuft, an einem Ort und im Hintergrund aktuell gehalten — damit Entscheidungen auf dem beruhen, was bekannt ist, und nicht auf dem, was zufällig im Raum war. Es entscheidet nie, rät nie und schreibt nie als Sie.",label:"Führungskräfte",headline:"Nichts, was das Unternehmen zugesagt hat, liegt nur in einer Erinnerung.",story:["Der Gründer und CEO eines Unternehmens mit etwa 90 Menschen. Kein Konzernvorstand mit Stabschef und zwei Assistenzen — jemand, der Investoren noch selbst antwortet, noch in Einstellungsgespräche gezogen wird und dessen Woche die Bedürfnisse anderer besetzt haben. Sein Anliegen war „Ich habe keine Zeit zum Denken“, und das ist nach unserer Erfahrung das einzige Anliegen, das CEOs wirklich haben.","Der Schaden sind nicht die verlorenen Stunden, sondern was sie kosten: Jede Entscheidung fällt in den elf Minuten zwischen zwei Terminen, auf Basis dessen, was zufällig gerade im Raum war. Termine, in die man kalt hineingeht. Zusagen, die laut gemacht und von niemandem behalten werden. Board-Vorbereitung, die pro Quartal ein Wochenende frisst. Dreihundert E-Mails am Tag, von denen zwölf zählen, weshalb die zwölf zu spät gefunden werden. Nichts davon ist ein Papierproblem — es ist ein Unternehmen, das auf dem läuft, was sein Gründer gerade im Kopf halten kann."],machinery:["Den Stand jeder Beziehung halten, auf der das Unternehmen läuft: was zuletzt vereinbart wurde, was noch offen ist, was versprochen wurde und bis wann","Dafür sorgen, dass nichts, was den Gründer braucht, ihn zu spät erreicht — und nichts, was ihn nicht braucht, ihn überhaupt erreicht, mit Begründung in beide Richtungen","Die eigenen Zahlen des Unternehmens daraufhin beobachten, was sich verändert hat, gegenüber der Erwartung, statt zu berichten, wie es steht","Die Board-Unterlagen aus denselben Quellen zusammenstellen, in fester Struktur","Benannte Wettbewerber, den Markt und relevante regulatorische Entwicklungen fortlaufend beobachten","Das Material für eine Entscheidung vor dem Termin zusammenhaben statt danach"],judgement:["Jede Entscheidung","Strategie","Menschen","Wofür das Unternehmen da ist"],builds:[{name:"Das Zusagenprotokoll",text:"Alles, was das Unternehmen zugesagt hat, wem gegenüber, bis wann — aus den Gesprächen gesammelt, in denen es tatsächlich zugesagt wurde, und nicht daraus, dass jemand daran denkt, es aufzuschreiben. Gründer machen sehr viele mündliche Zusagen und erinnern sich an vielleicht die Hälfte, und die vergessene Hälfte ist die, die eine Beziehung beschädigt."},{name:"Der Stand jeder Beziehung",text:"Das Wertvollste auf dieser Liste. Vor jedem Termin: was zuletzt vereinbart wurde, wie es damit steht, was noch offen ist, die wahrscheinliche Bitte, die relevanten Zahlen. Keine Zusammenfassung eines Mailverlaufs — der laufende Stand dieser Beziehung, aktuell gehalten, ob jemand danach fragt oder nicht. In ein Meeting zu gehen und zu wissen, was letztes Mal versprochen wurde, verändert, was darin passiert. Das allein hat den Auftrag gerechtfertigt."},{name:"Die Veränderungsbeobachtung",text:"Die eigenen Zahlen des Unternehmens, beobachtet daraufhin, was sich bewegt hat, um wie viel, gegenüber der Erwartung. Keine weitere Bildschirmseite voller Diagramme. Die braucht ein CEO nicht; er braucht etwas, das schon gemerkt hat, was wichtig ist."},{name:"Was Sie erreicht, und warum",text:"Das Unternehmen erzeugt weit mehr, was die Aufmerksamkeit des Gründers will, als der Gründer Aufmerksamkeit hat. Also entscheidet etwas — und zeigt seine Begründung: Nichts wird gelöscht, nichts automatisch beantwortet, nichts versteckt, und was beiseitegelegt wurde, bleibt sichtbar und prüfbar. Ein CEO, der vermutet, dass das System etwas verbirgt, kontrolliert alles nach, und dann schadet es mehr, als es hilft."},{name:"Der Blick nach außen",text:"Benannte Wettbewerber, der Markt und die regulatorische Entwicklung, die Ihr Feld erreicht, bevor sie Ihr Postfach erreicht. Das ist die Arbeit, die jeder Gründer vorhat und für die keiner einen Nachmittag hat."},{name:"Board-Unterlagen zusammenstellen",text:"Feste Struktur, aktuelle Zahlen, die Zusagen des Vorquartals und ihr Stand. Aus einem Wochenende wird ein Vormittag — und der Vormittag geht in die Erzählung, also in den Teil, der vorher eine Stunde am Ende bekam."}],stops:{title:"Es entscheidet nie und spricht nie als Sie.",text:["Keine externe Kommunikation wird in Ihrer Stimme erzeugt — nicht an Investoren, nicht an Mitarbeitende, nicht öffentlich. Ein CEO, dessen Worte sich erzeugen lassen, hat ein schwer umkehrbares Problem: Sobald es intern bekannt wird, liest jeder seine Nachrichten mit einer Frage im Hinterkopf.","Es empfiehlt nie eine Vorgehensweise in strategischen Fragen. Es trägt zusammen, was bekannt ist, markiert, was unbekannt ist, und hört auf. Die Versuchung, einem einsamen Gründer einen KI-Berater zu bauen, ist groß — und was dabei herauskommt, ist selbstsicher, plausibel und losgelöst von allem, was das System über das Unternehmen wirklich wissen kann. Und aus diesem Postfach geht nichts automatisch raus. Alles wartet auf Sie."]},proof:"Eingehaltene Zusagen, statt später von der Person entdeckt, der sie gemacht wurden. Termine, in die man geht und weiß, was zuletzt vereinbart wurde. Stunden Board-Vorbereitung. Und das, worum es anfangs eigentlich ging: Stunden ungestörter Denkzeit pro Woche, im Kalender zählbar und damals nahe null.",refuse:"Jede Variante eines KI-Beirats, Strategiegenerators oder Entscheidungsempfehlers. Ebenso alles, was die Stimme des CEO für externe Kommunikation erzeugt. Beides wurde gewünscht. Beides abgelehnt.",cost:"Fünfzehn Minuten jeden Morgen im ersten Monat, um zu prüfen, was das System für nötig und für unnötig hielt. Danach nichts.",quotes:[{text:"Neunzig Menschen, dreihundert E-Mails am Tag, zwölf davon relevant, und keine Stunde irgendwo, die mir gehörte. Das Kurzbriefing sind neunzig Sekunden Lesen, und es hat verändert, was in den Terminen passiert, weil ich jetzt hineingehe und weiß, was ich letztes Mal versprochen habe. Er wollte nichts bauen, das für externe Nutzung in meiner Stimme schreibt, und hat erklärt, was intern passiert, sobald Menschen das vermuten — das hatte ich nicht zu Ende gedacht. Aus meinem Postfach geht nichts automatisch raus. Ich bin von faktisch null Stunden Denkzeit pro Woche auf etwa zehn gekommen.",name:"Gründer und CEO, ~90 Beschäftigte"}]},{slug:"volunteer-orgs",title:`KI für Vereine: Förderanträge in drei Stunden — ${e.brand}`,metaDescription:"Alle wiederverwendbaren Fakten über Ihren Verein an einer Stelle, in die Struktur jedes Fördergebers gebracht. Anträge in drei Stunden statt zwei Tagen. Kostenlose Werkzeuge.",label:"Vereine",headline:"Förderanträge in drei Stunden statt zwei Tagen, mit kostenlosen Werkzeugen.",story:["Ein eingetragener Verein — rund 40 aktive Ehrenamtliche, eine Teilzeitkoordinatorin, finanziert aus Förderungen, Mitgliedsbeiträgen und Spenden. Die Koordinatorin macht die Arbeit von drei Personen auf 20 Wochenstunden, und der Vorstand wollte das vor der nächsten Förderrunde gelöst haben.","Das größte Problem sind die Förderanträge. Jeder Fördergeber will dieselben Informationen in anderer Struktur — Organisationsbeschreibung, Projektplan, Budget, Wirkungsnachweis, bisherige Förderung — und jeder Antrag kostet zwei volle Tage. Diese Tage fehlen bei der eigentlichen Arbeit, um die es dem Verein geht. Dahinter: die Dienstplanung für 40 Ehrenamtliche, die Mitgliederverwaltung, der Spenderdank und der Jahresbericht."],machinery:["Die wiederverwendbaren Fakten aktuell halten: Auftrag, Geschichte, Struktur, Personal, Finanzen, Projekte, Wirkungszahlen","Diese Fakten in die geforderte Struktur und Zeichenbegrenzung jedes Fördergebers bringen","Jede Frist, Berichtspflicht und jedes Ergebnis über alle Anträge halten, die der Verein je gestellt hat","Vierzig Ehrenamtliche abgedeckt halten, ohne dass eine Person den ganzen Dienstplan im Kopf trägt","Die Mitgliederseite am Leben halten: Eintritte, Beiträge, Austritte, Beitragseinzug, und die Spender, denen nie gedankt wurde","Aktivitätsdaten laufend erfassen, damit der Wirkungsbericht keine Archäologie wird"],judgement:["Wofür der Verein da ist","Welchen Fördergeber Sie ansprechen und was Sie ihm versprechen","Jede Aussage über Wirkung","Ihre Beziehungen zu den Ehrenamtlichen"],builds:[{name:"Das Kerndokument",text:"Jede wiederverwendbare Tatsache über den Verein, einmal geschrieben, aktuell gehalten, mit Quelle für jede Zahl. Das Wertvollste, was wir gebaut haben — und im Kern eine gut geordnete Textdatei."},{name:"Der Antragsentwurf",text:"Sie geben die Fragen und Zeichenbegrenzungen eines Fördergebers ein. Heraus kommt ein Entwurf, der aus dem Kerndokument gebaut ist. Aus zwei Tagen werden etwa drei Stunden, und jede Aussage lässt sich auf das Kerndokument zurückführen. So wird unter Fristdruck nichts erfunden — und genau dann erfinden Organisationen Dinge."},{name:"Der Fristenkalender",text:"Antragsfristen, Berichtsfristen und was wem versprochen wurde. Versäumte Berichte sind der Weg, auf dem kleine Vereine ihre Fördergeber still verlieren."},{name:"Der Dienstplan",text:"Verfügbarkeiten rein, Schichten raus, Lücken früh genug sichtbar, um etwas dagegen zu tun. Es war der größte wöchentliche Zeitfresser der Koordinatorin — und vor allem lag er vollständig in ihrem Kopf, was ein echtes Risiko ist in einem Verein, in dem die bezahlte Stelle alle paar Jahre wechselt."},{name:"Das Aktivitätsprotokoll",text:"Dreißig Sekunden nach jedem Termin: Was ist passiert, wie viele Menschen, was fiel auf. Ein Jahr später entsteht der Wirkungsbericht aus echten Aufzeichnungen statt aus einer panischen Rekonstruktion im Januar."}],stops:{title:"Keine Wirkungsaussage wird erzeugt, und keine Nachricht an Fördergeber geht automatisch raus.",text:["Jede Zahl in einem Förderantrag stammt aus dem Aktivitätsprotokoll oder der Buchhaltung. Gibt das Protokoll sie nicht her, sagt der Antrag das. Wirkung gegenüber einem Fördergeber zu übertreiben ist Betrug. Es passiert versehentlich unter Fristdruck, und ein flüssig schreibendes Werkzeug macht diesen Fehler leichter — deshalb ist der Antragsentwurf so gebaut, dass er sich weigert. Fehlt der Beleg, schreibt er „Das messen wir noch nicht“ und überlässt die Stelle einem Menschen.","Über Betreute wird nichts geschrieben. Wo der Verein mit schutzbedürftigen Menschen arbeitet, gelangen überhaupt keine personenbezogenen Daten in ein externes Werkzeug. Nur zusammengefasste Zahlen. Und alles muss auf kostenlosen oder fast kostenlosen Werkzeugen laufen und in zwei Jahren von der nächsten Person bedienbar sein — alles, was ein Abo oder eine Fachkraft braucht, wird aufgegeben."]},proof:"Stunden pro Förderantrag. Eingereichte Anträge pro Jahr — die sich etwa verdoppelt haben, und das ist der gesamte wirtschaftliche Sinn. Eingehaltene Berichtsfristen. Stunden der Koordinatorin für Verwaltung gegenüber der eigentlichen Arbeit. Ob das Aktivitätsprotokoll nach sechs Monaten noch geführt wird.",refuse:"Wenn ein Verein eine Website, ein CRM und eine Spendenplattform will. Das ist ein anderes Projekt mit laufenden Kosten, die er nicht tragen kann, und es wird binnen eines Jahres aufgegeben. Eine gut gepflegte Tabelle und ein dokumentierter Ablauf überleben die meisten Systeme, die für solche Organisationen gebaut werden.",cost:"Dreißig Sekunden nach jedem Termin für das Aktivitätsprotokoll. Das Kerndokument aktuell halten, wenn sich etwas ändert. Nichts, was jeden Monat Geld kostet.",quotes:[{text:"Ein Förderantrag hat zwei volle Tage gekostet, und diese Tage kamen aus der Arbeit, für die es den Verein überhaupt gibt. Alles Wiederverwendbare über uns liegt jetzt an einer Stelle und wird in die Struktur gebracht, die ein Fördergeber verlangt — das dauert etwa drei Stunden. Wir haben die Zahl der eingereichten Anträge verdoppelt, und das ist der gesamte wirtschaftliche Sinn. Er hat es so gebaut, dass der Antrag schreibt, dass wir es nicht messen, wenn der Beleg nicht im Aktivitätsprotokoll steht — statt mich um Mitternacht vor einer Frist eine Zahl improvisieren zu lassen.",name:"Koordinatorin, eingetragener Verein, ~40 Ehrenamtliche"}]},{slug:"research",title:`KI für die Forschung: Anträge in zehn Tagen — ${e.brand}`,metaDescription:"Wiederverwendbarer Antragstext für jede Ausschreibung, ein Betreuungsprotokoll, Literatursichtung und reproduzierbare Abbildungen. Es erfindet nie eine Quellenangabe.",label:"Forschung",headline:"Zwei Professuren kamen von nahezu null Forschungsstunden auf acht bis zwölf pro Woche.",story:["Zwei sehr verschiedene Menschen mit demselben Kalenderproblem. Die Professur: neun SWS Lehrdeputat, vier bis fünfzehn Promovierende, Prüfungsausschuss, Berufungskommission und Fakultätsrat, sechs bis zehn unbezahlte Gutachten im Jahr und zwei bis drei Anträge, weil der Lehrstuhl auf Drittmitteln läuft. Eingestellt für die Forschung, forscht sie sonntags, wenn überhaupt. Und die Promovierende: Jahr drei eines WissZeitVG-Vertrags, der in Jahr vier endet, 900 ungelesene PDFs, drei geschriebene Kapitel, die nicht mehr zusammenpassen, und eine Auswertung, die ihre eigenen Abbildungen nicht mehr reproduzieren kann.","Für Professuren ist es der Antrag. Eine DFG-Sachbeihilfe braucht Stand der Forschung, Vorarbeiten, Arbeitsprogramm, Mittelbegründung, Lebenslauf, Publikationsliste in der DFG-eigenen Struktur, einen Datenmanagementplan, eine Ethikerklärung und Maßnahmen zur Chancengleichheit. Etwa sechzig Prozent dieses Textes gab es schon, in drei früheren Anträgen, in leicht falschen Formaten — und er wird trotzdem neu geschrieben, über fünf Wochen aus Abenden und Wochenenden, weil das Suchen der alten Fassung mühsamer erscheint als das Neutippen. Für Promovierende sind es sechshundert Abstracts, die gesichtet werden müssen, und später die schlimmere Frage: Welche Version der Auswertung hat auf welchem Datenstand Abbildung 3 erzeugt?"],machinery:["Literatur sichten: alles Neue in einem definierten Feld zusammentragen und nach Relevanz für eine Frage sortieren","Eine Literaturdatenbank aufräumen: Dubletten entfernen, Angaben reparieren, jede Quelle gegen ihren offiziellen Eintrag prüfen","Eine Publikationsliste in DFG-, ERC-, NSF-, Europass- oder Hausstruktur umformatieren","Den wiederverwendbaren Antragstext aktuell halten und in Struktur und Seitengrenzen einer Ausschreibung bringen","Ausschreibungen, Zwischen- und Abschlussberichte, Gutachtenzusagen und Prüfungstermine verfolgen","Das Betreuungsprotokoll für jede Promovierende führen","Bewerbungen in einem Berufungsverfahren gegen die veröffentlichten formalen Kriterien auf Vollständigkeit prüfen","Das Reproduzierbarkeitsprotokoll führen: welche Daten, welche Version der Auswertung, welche Abbildung"],judgement:["Die Forschungsfrage. Die Hypothese. Die Interpretation","Ob ein Ergebnis etwas bedeutet","Die Beurteilung eines Menschen — im Gutachten, in der Verteidigung, im Berufungsverfahren","Was begutachtet wird und zu welchem Schluss ein Gutachten kommt"],builds:[{name:"Der Antragskern",text:"Ein gepflegter Speicher: der Lebenslauf in jedem je verlangten Format, die Publikationsliste, die Beschreibung der Arbeitsgruppe, die Infrastruktur, die Vorarbeiten-Absätze je Forschungslinie mit ihren Abbildungen und Quellen, Ergebnisse früherer Projekte, die Vorlage für den Datenmanagementplan, die Chancengleichheitsmaßnahmen. Jeder Eintrag datiert und mit Quelle. Etwa zwei Wochen Aufbau, überwiegend Herausziehen aus drei alten Anträgen — und das letzte Mal, dass diese Absätze aus dem Nichts geschrieben werden."},{name:"Das Antragsgerüst",text:"Sie geben Struktur, Überschriften und Seitengrenzen einer Ausschreibung ein. Heraus kommt ein Gerüst, in dem das Kernmaterial schon in etwa der richtigen Länge an der richtigen Stelle steht und jeder Abschnitt, der eigenes Denken braucht, leer und beschriftet ist. Aus fünf Wochen werden etwa zehn Tage, und fast alle zehn gehen ins Arbeitsprogramm — den Teil, der gefördert wird."},{name:"Das Betreuungsprotokoll",text:"Eine private Datei je Promovierender: was vereinbart wurde, was geschah, Meilensteine gegen die Betreuungsvereinbarung, genannte Hindernisse. Neunzig Sekunden Diktat nach jedem Gespräch. Das würden wir zuerst einrichten, wenn wir nur eines einrichten dürften — weil Gespräche heute damit beginnen, dass beide sich zu erinnern versuchen, weil Gutachten zwei Jahre später aus dem Nichts entstehen und weil das Protokoll vier Monate früher zeigt, dass jemand still in Schwierigkeiten steckt."},{name:"Die Literatursichtung",text:"Für Promovierende: sechshundert Abstracts gegen Ein- und Ausschlusskriterien, die vorher aufgeschrieben wurden. Jede Entscheidung mit dem Kriterium festgehalten, das sie ausgelöst hat, jeder Grenzfall für Sie markiert. Für systematische Reviews folgt das PRISMA und liefert die Zahlen für das Flussdiagramm nebenbei."},{name:"Das Reproduzierbarkeitsprotokoll",text:"Welcher Datenstand, welche Version der Auswertung, welche Software-Umgebung, welche Ausgabe. Jede Abbildung trägt den genauen Befehl, der sie erzeugt hat. In Jahr eins an einem Nachmittag eingerichtet, in Jahr vier einen Monat wert."}],stops:{title:"Es erzeugt nie eine Quellenangabe und fasst nie eine Arbeit zusammen, die Sie zitieren werden.",text:["Quellen kommen aus Ihrer Literaturverwaltung und werden gegen den offiziellen Eintrag der jeweiligen Arbeit geprüft. Nichts, was Text erzeugt, darf eine Quellenangabe erzeugen — nie, unter keinem Vorwand. Erfundene Quellen sind das häufigste und zerstörerischste Versagen von Sprachmodellen in der Forschung, und eine müde Autorin erkennt sie um 23 Uhr nicht, weil sie genau richtig aussehen. Tausend Abstracts zu sichten, um vierzig Arbeiten zu finden, ist Routinearbeit; diese vierzig zu lesen ist der Beruf — die Sichtung liefert deshalb Titel, Abstracts und Links, nie eine Zusammenfassung, die als ausreichend präsentiert wird.","Kein Manuskript im Begutachtungsverfahren berührt einen externen Dienst: Peer Review ist vertraulich, und ein Manuskript ist unveröffentlichte Arbeit, die jemand anderem gehört. Das System schreibt nie das Argument, die Hypothese oder die Interpretation. Es reiht nie Bewerbungen in einem Berufungsverfahren — ein solches Verfahren ist gerichtlich überprüfbar, dokumentationspflichtig und unterliegt dem AGG; wir haben das zweimal abgelehnt. Keine Daten werden erfunden, keine Abbildung erzeugt, keine Bereinigung geschieht still: Roh bleibt roh. Jede Zusammenarbeit endet mit einer einseitigen Übersicht, die Sie behalten und die festhält, welche Aufgaben ein KI-Werkzeug genutzt haben und welche Offenlegungsregeln von Fördergebern und Verlagen gelten."]},proof:"Tage von der Ausschreibung bis zum eingereichten Antrag: typisch von fünf Wochen auf etwa zehn Arbeitstage. Eingereichte Anträge pro Jahr. Betreuungsgespräche mit schriftlichem Protokoll: von gelegentlich auf alle. Abbildungen, die sich mit einem einzigen Befehl reproduzieren lassen: alle. Und das Einzige, was wirklich zählt — Forschungsstunden pro Woche, die bei beiden Professuren von nahezu null auf acht bis zwölf gingen.",refuse:"Wenn jemand einen Textgenerator für Aufsätze will — zweimal gefragt, als „ein erster Entwurf der Einleitung“ und „nur der Related-Work-Teil“. Der Related-Work-Teil ist genau die Stelle, an der Sie zeigen, dass Sie das Feld gelesen haben. Ebenso, wenn ein Fachbereich Publikationskennzahlen pro Person will, was Überwachung im bibliometrischen Kostüm ist. Und wenn eine Promovierende eine Betreuung braucht statt eines Systems, was die traurigste Variante ist.",cost:"Zwei Wochen, um den Text aus alten Anträgen herauszuziehen und den Kern aufzubauen, einmalig. Neunzig Sekunden Diktat nach jedem Betreuungsgespräch. Und die Disziplin, die vierzig gefundenen Arbeiten zu lesen, was immer schon der Beruf war.",quotes:[{text:"Sechzig Prozent jedes Antrags existierten bereits, in drei früheren Anträgen, in leicht falschem Format, und ich habe es jeden März neu getippt, weil Suchen schwerer schien. Zwei Wochen Extraktion, und seitdem habe ich diese Seiten nicht mehr aus dem Nichts geschrieben. Eine DFG-Einreichung, die fünf Wochen dauerte, dauert jetzt etwa zehn Arbeitstage, und fast alle gehen ins Arbeitsprogramm, den Teil, der gefördert wird. Er hat nichts eine Quellenangabe erzeugen lassen — Referenzen lösen über die DOI auf oder sie erscheinen nicht — und angesichts dessen, was ich bei Kolleginnen habe passieren sehen, ist diese Regel der Grund, warum ich ihn überhaupt herangelassen habe.",name:"Professor (W3), Naturwissenschaften"},{text:"Jahr drei, neunhundert ungelesene PDFs, drei Kapitel, die nicht mehr zusammenpassten, und vierzig Minuten mit meinem Betreuer alle sechs Wochen. Die Sichtungsstrecke hat sechshundert Abstracts auf die vierzig gebracht, die ich wirklich lesen musste, und hat protokolliert, welches Kriterium jede Entscheidung erzeugt hat. Die Reproduzierbarkeit war an einem Nachmittag eingerichtet, und ich weiß jetzt, welche Skriptversion welche Abbildung gemacht hat — ein langweiliger Satz, der mich in meiner Verteidigung gerettet hat. Er hat mir außerdem freundlich gesagt, dass ich eigentlich eine Betreuung brauche, und er hatte recht.",name:"Doktorandin, Geisteswissenschaften"}]}]},how:{title:"Wie die Beratung abläuft, Schritt für Schritt.",steps:[{title:"Zuerst: Wir lernen Ihr Geschäft kennen.",text:"Wie Sie Aufträge gewinnen, wo Geld verloren geht, womit Ihre Leute ihre Tage verbringen, und was Sie stillschweigend nicht mehr für möglich halten. Kein Workshop, kein Fragebogen. Wir sitzen im Haus und stellen Fragen."},{title:"Dann: Wir zeichnen auf, was KI öffnet, und wo sie aufhört.",text:"Eine Seite. Auf der einen Seite: die Leistungen, die Sie anbieten könnten, das Tempo, das Sie erreichen könnten, die Kosten, die Sie senken könnten. Auf der anderen: was bei Ihren Leuten bleibt, weil Ihr Name, Ihr Urteil oder Ihre Beziehungen darauf stehen. Ihnen vorgelesen, und Sie geben jede Zeile frei oder streichen sie, bevor etwas gebaut wird. Diese Seite ist der Plan."},{title:"Dann: Wir beweisen die ersten Ideen live.",text:"In Ihrem Büro, mit Ihren Daten, in Ihren eigenen Konten. Zwei oder drei Ideen von der Seite werden getestet. Was funktioniert, bleibt. Was scheitert, kostet Sie einen Nachmittag und bringt Ihnen eine Erkenntnis."},{title:"Zuletzt: Ihr Team übernimmt, und wir entscheiden, wie es weitergeht.",text:"Die Leute, die das Funktionierende betreiben werden, lernen, die Regeln ohne uns zu ändern, und jedes System bekommt eine namentlich benannte Verantwortliche bei Ihnen, die schon selbst eine Regel geändert hat. Dann schauen wir gemeinsam auf die Seite und entscheiden, ob wir die Rolle Head of AI für die kommenden Monate übernehmen."}],termsTitle:"Wie es kalkuliert wird und wie es endet.",terms:["Ein Festpreis für das Mandat, schriftlich angeboten nach dem kostenlosen Erstgespräch. Eine Rechnung, kein Tagessatz-Zähler, keine Spesen.","Die Rolle Head of AI läuft monatlich, und Sie können mit einem Monat Frist jederzeit aufhören, ohne Begründung.","Modell- und Cloud-Nutzung wird über Ihre eigenen Konten abgerechnet, zum Selbstkostenpreis. Wir verkaufen sie nicht weiter und schlagen nichts auf.","Der Bau der größeren Systeme, die das Mandat findet, wird getrennt angeboten, je System, nachdem wir die Arbeit gesehen haben. Vorher geben wir keinen Preis für einen Bau ab.","Kommen wir früh zu dem Ergebnis, dass sich hier nichts lohnt, sagen wir das, hören auf und rechnen nur die bereits geleisteten Tage ab."]},offers:{title:"Drei Wege, mit uns zu arbeiten.",businessLabel:"Für ein Unternehmen",individualLabel:"Für eine Einzelperson",items:[{name:"Beraten",text:"Wir finden heraus, was KI für Sie verändert und was nicht, und schreiben es auf eine Seite, mit der Sie arbeiten können.",business:"Wir lernen, wie Sie Geld verdienen und wo Sie feststecken, gehen die Woche mit den Menschen durch, die die Arbeit tatsächlich machen, und markieren, wo KI etwas Neues für Sie öffnet — und wo sie aufhören muss, weil Ihr Name, Ihr Urteil oder Ihre Beziehungen daran hängen. Sie bekommen eine Seite, Zeile für Zeile vorgelesen, und Sie geben jede Zeile frei oder streichen sie, bevor irgendetwas gebaut wird.",individual:"Sie bringen die Frage — eine Entscheidung, einen Plan, eine Idee, den nächsten Schritt in Ihrer Arbeit. Wir bringen, was KI dazu kann und nicht kann, in klarer Sprache, und eine klare Empfehlung, mit der Sie noch am selben Tag etwas anfangen können. Eine Sitzung, oder ein paar.",asks:"Zugang zu Ihrem Betrieb und Ihrer Führung, in einer Form, die wir vorher mit Ihnen vereinbaren."},{name:"Einführen",text:"Wir bringen KI in Ihre Hände und lassen Sie damit arbeiten können, ohne uns.",business:"Schriftliche Regeln, was in welches Werkzeug darf und was nicht, die Werkzeuge ausgewählt und in Ihren eigenen Konten eingerichtet, Ihr Team an Ihren eigenen Dokumenten geschult, und für jedes System eine namentlich benannte Verantwortliche bei Ihnen, die darin schon eine Regel geändert hat. Das ist auch die Rolle als Head of AI, wenn Sie sie dauerhaft wollen: Richtung, Experimente, Werkzeugentscheidungen schriftlich, und der Experte im Raum, wenn eine Kundin oder ein Investor nach KI fragt.",individual:"Ihre eigenen Werkzeuge, in Ihren eigenen Konten, eingerichtet für das, was Sie tatsächlich tun — und Sie lernen, damit zu arbeiten, in Ihrem Tempo, an Ihrem eigenen Material. Dazu gehört auch, einem Kind zu zeigen, wie das funktioniert und wo es sich irrt, auf seiner Höhe, mit den Hausregeln dazu.",asks:"Einen Platz am Tisch, wenn über KI entschieden wird, und Zugang zu den Menschen, deren Arbeit es berührt."},{name:"Bauen",text:"Wenn die Antwort ein Ding ist und keine Gewohnheit, bauen wir es.",business:"Systeme, die von selbst laufen, an Ihrem eigenen Material, für alle, deren Arbeit es berührt — pro System angeboten, nachdem wir die Arbeit gesehen haben, nie vorher. Es läuft in Ihren Konten, unter Ihren Zugängen, mit Ihren Schlüsseln, und der Code liegt in Ihrem Repository. Jedes System kommt mit schriftlicher Übergabe, denn der Sinn ist, dass es weiterläuft, ob wir noch da sind oder nicht.",individual:"Ein Prototyp, den Sie einer Mitgründerin oder einem Investor zeigen können, ein Werkzeug, das Sie jeden Tag benutzen, die erste Version der Plattform hinter dem Unternehmen, das Sie gründen. Angeboten, nachdem wir es verstanden haben, gebaut in Ihren Konten, und Ihres ab der ersten Zeile Code.",asks:"Die Menschen, die die Arbeit machen, für die Stunden, die es braucht, das Detail richtig zu bekommen."}]},team:{path:"/fuer-unternehmen/",label:"Für Unternehmen",title:`KI für Ihr Unternehmen — ${e.brand}, KI-Beratung in Berlin`,metaDescription:`Wir beraten, wir führen ein, und wir bauen, was gebaut werden muss. ${e.brand} bringt einen erfahrenen KI-Experten in Unternehmen, Start-ups, Teams und Forschungsgruppen jeder Größe und Branche. Alles läuft in Ihren Konten, und jede Entscheidung bleibt bei Ihrem Team.`,headline:"Der KI-Experte, der Ihrem Unternehmen fehlt.",intro:["Diese Seite ist für die Person, die den Laden führt, was immer der Laden ist: ein Unternehmen, ein Start-up, eine Abteilung in einem größeren Haus, eine Praxis, ein Büro gleich welchen Gewerbes, eine Forschungsgruppe, ein Team jeder Art. Sie sehen, dass KI Ihre Branche verändert. Sie haben keinen Platz für eine KI-Abteilung und keine Zeit, durch Versuch und Irrtum herauszufinden, was davon für Sie zählt.","Wir werden dieser Experte. Zum Anfang die Beratung in Ihrem Unternehmen, danach die Rolle Head of AI auf Zeit, so lange es sich lohnt. Wir bringen die Richtung, die Ideen und die Experimente, Ihre Leute bringen das Wissen über das Geschäft, und jede Entscheidung bleibt bei Ihnen."],offersTitle:"Drei Wege, mit uns zu arbeiten.",dayTitle:"Was die Rolle Head of AI abdeckt.",dayIntro:"Eine laufende Liste, in der Reihenfolge, in der es meistens auftaucht.",day:["Agenten, die laufen, ohne dass jemand sie startet: Arbeit, die früher darauf wartete, dass jemand eine freie Stunde hat, läuft durchgehend auf Ihren eigenen Systemen","Fast jede Woche ein neues Experiment: eine Leistung, die Sie verkaufen könnten, ein Ablauf, den Sie halbieren könnten, ein Werkzeug, das einen echten Test verdient","Welchen KI-Werkzeugen Sie Ihre Daten anvertrauen und welche Sie ablehnen, für Sie entschieden, schriftlich","Kundenangebote, Ausschreibungen und Förderanträge, die KI brauchen und glaubwürdig sein müssen","Was Ihre Wettbewerber und Ihre Branche gerade versuchen, und was davon sich zu kopieren lohnt","Fragen der Mitarbeitenden, am Schreibtisch beantwortet statt im Workshop","Die schriftlichen Regeln: was KI in Ihrem Unternehmen darf und was nicht, aktuell gehalten","Für Forschungsgruppen: welche Modelle heute was können, welche Experimente den Monat einer Doktorandin wert sind, und wo die Wissenschaft menschlich bleiben muss"],staysTitle:"Was bei Ihrem Team bleibt.",stays:["Jede Entscheidung","Jede Unterschrift, Note, Bewertung und Diagnose","Jede Beziehung zu Mandanten, Patienten, Schülern und Kollegen","Die Freiheit, jeden Monat aufzuhören"],newFieldTitle:"Ein Feld, das wir noch nie gesehen haben.",newField:"Ein Hersteller, eine Spedition, eine Privatklinik, ein Fonds. In jeder Branche haben wir noch nicht gearbeitet. In jedem Feld bisher lief das Mandat gleich ab: Wir lernen das Geschäft kennen, wir zeichnen auf, wo KI etwas Neues öffnet und wo sie aufhören muss, wir führen die ersten Experimente durch. Was wir bauen, ändert sich von Feld zu Feld vollständig. Wie wir es herausfinden, musste sich bisher nicht ändern — und sollte Ihre Branche die Ausnahme sein, hören Sie das früh und nicht am Ende.",continuityTitle:"Ein kleines Unternehmen, mit Absicht — und nichts, was mit uns stehen bleibt.",continuityIntro:`${e.brand} ist ein kleines Unternehmen, gebaut um einen erfahrenen KI-Experten, mit Absicht. Sie bekommen die Person, die die Systeme gebaut hat, an Ihrem Tisch, ohne Kundenbetreuer zwischen Ihnen und der Arbeit und ohne Junior, der an Ihren Daten lernt. Das ist nur dann sicher, wenn nichts Wichtiges an uns hängt — also hängt nichts daran.`,continuity:[{title:"Alles gehört von Tag eins Ihnen.",text:"Jedes System läuft in Ihren Konten, unter Ihren Zugängen, auf Ihrer Infrastruktur. Der Code liegt in Ihrem Repository. Die API-Schlüssel sind Ihre und werden direkt Ihnen abgerechnet, sodass Sie die Kosten sehen und begrenzen können. Wir halten keinen Zugang, den Sie nicht an einem Nachmittag entziehen können."},{title:"Jedes System bekommt eine schriftliche Übergabe.",text:"Geschrieben in der Woche, in der das System gebaut wird, nicht in der Woche, in der wir gehen: was wo läuft, welcher Dienst was tut, wie man die Regeln ändert, wie man es abschaltet, was dann nicht mehr geht und worauf man schaut, wenn etwas seltsam aussieht. Geschrieben für die Person in Ihrem Team, die es übernehmen wird, und geprüft, indem sie es benutzt, während wir zusehen."},{title:"Für jedes System ist eine Person bei Ihnen benannt.",text:"Wir übergeben nicht „an das Team“. Vor dem Livegang ist eine Ihrer Leute darin geschult, hat selbst eine Regel geändert und ist in der Übergabe als verantwortlich benannt."},{title:"Reaktionszeiten, schriftlich.",text:"Am selben Werktag für alles, was kaputt ist, zwei Werktage für alles andere, und ein festes Zeitfenster pro Woche, in dem Sie wissen, wo Sie uns finden. Sind wir länger als eine Woche weg, bekommen Sie die Termine vorher."},{title:"Wenn wir aufhören, hört nichts auf.",text:"Kein System braucht eine Lizenz, ein Konto, einen Server oder ein Abo von uns. Wären wir morgen verschwunden, liefe alles weiter, und Ihre benannten Verantwortlichen könnten es weiter ändern. Daran messen wir unsere Bauweise, und Sie können es in den Vertrag schreiben."},{title:"Wir arbeiten im Mandat, nicht als Personal.",text:"Die Rolle Head of AI ist ein Mandat mit eigener Leistungsverantwortung, eigenen Arbeitsmitteln und mehreren Auftraggebern — kein Anstellungsverhältnis, keine Weisungsbindung, keine Eingliederung in Ihre Arbeitsorganisation. Wenn Ihre Finanz- oder Personalabteilung das vorab bestätigt haben möchte, schreiben wir es in den Vertrag und lassen den Status auf Wunsch vorher förmlich feststellen."}],notUsTitle:"Wo wir nicht der richtige Dienstleister sind.",notUs:["Wir haben keine 24/7-Rufbereitschaft und betreiben Ihre Produktionssysteme nicht für Sie. Wenn Sie ein Betriebsteam mit Pager brauchen, brauchen Sie einen Managed-Service-Anbieter, und wir sagen das im Erstgespräch.","Wir sind nicht nach ISO 27001, SOC 2 oder TISAX zertifiziert und haben kein Sicherheitsteam und kein Penetrationstest-Programm. Wenn Ihr Einkauf eine Zertifizierung verlangt, sind wir nicht der richtige Dienstleister, und Sie hören das, bevor Sie Zeit in uns investieren.","Wir nehmen nur wenige Mandate gleichzeitig an. Wenn wir voll sind, sagt die Zeile oben auf der Startseite das.","Wir bauen nichts, was einem Menschen eine Entscheidung, eine Diagnose, eine Bewertung, eine Note oder eine Unterschrift abnimmt. Wir haben deswegen Aufträge abgelehnt, und wir würden Ihren ablehnen."]},individuals:{path:"/fuer-einzelpersonen/",label:"Für Einzelpersonen",title:`Ein KI-Experte für eine Person — ${e.brand}`,metaDescription:"Für alle, die einen KI-Experten an ihrer Seite brauchen könnten, ohne ein Unternehmen zu führen: eine Entscheidung, eine Idee, eine Gründung, eine Fähigkeit, ein Kind. Beratung, Hilfe beim Machen und Bauen, in klarer Sprache, zum schriftlich vereinbarten Festpreis. Das Erstgespräch ist kostenlos.",headline:"Ein KI-Experte an Ihrer Seite, für das, was vor Ihnen liegt.",intro:["Das meiste, was über KI geschrieben wird, ist für Unternehmen geschrieben. Die meisten Entscheidungen, bei denen sie helfen könnte, trifft eine einzelne Person: was mit einer großen Summe Geld geschehen soll, ob eine Idee ein Jahr Ihres Lebens wert ist, wie man das Unternehmen gründet, von dem Sie immer reden, in welche Ihrer Fähigkeiten Sie als Nächstes investieren, was Sie Ihrem Kind über eine Technik sagen, die sein Arbeitsleben prägen wird.",`${e.brand} gibt Ihnen denselben Experten, den ein Unternehmen bekommt, auf eine Person zugeschnitten. Sie bringen die Frage. Wir bringen, was KI dazu kann und nicht kann, in klarer Sprache, ohne ein eigenes Produkt, das wir Ihnen verkaufen wollen — und wo sie hilft, sorgen wir dafür, dass Sie sie danach selbst nutzen können.`],lanesTitle:"Drei Wege, mit uns zu arbeiten.",recordTitle:"Wer schon durch diese Tür gekommen ist.",recordIntro:"Menschen, die ohne ein Unternehmen im Rücken kamen, sortiert nach dem, womit sie kamen.",record:{"job-seekers":"Bewerbungen und Gespräche für Menschen, die die Antworten nicht mehr geöffnet haben. Die meisten von ihnen sind über diesen Weg in Arbeit.",athletes:"Halbprofis, die noch am selben Abend ein Video brauchten, das ein Scout öffnet, und ein Trainingslog, das sie tatsächlich geführt haben.","home-buyers":"Weniger Wohnungen statt mehr: eine Auswahl, die zu den echten Kriterien passt, und die Unterlagen vor der Besichtigung gelesen statt danach.",teachers:"Korrektur und Zeugniszeit auf Abende gekürzt. Das Werkzeug findet den Beleg; die Lehrkraft gibt die Note.",coaches:"Ein-Personen-Studios. Bei drei von fünf lautete die ehrliche Antwort: ein Buchungssystem, keine KI — und das haben wir gesagt.","online-shoppers":"Der kleinste Auftrag auf dieser Liste. Gekündigte Abos und rechtzeitige Rücksendungen haben das Honorar binnen eines Monats bezahlt."},runsTitle:"So läuft es ab.",runs:["Sie buchen ein kostenloses 30-Minuten-Gespräch oder schreiben uns. Keine Vorbereitung; ein paar Sätze dazu, womit Sie es zu tun haben, genügen.","Wir sagen Ihnen ehrlich, ob KI hier etwas verändert. Etwa jedes dritte Mal lautet die Antwort nein, und Sie gehen mit einer Empfehlung statt eines Angebots.","Wenn ja, bekommen Sie einen Festpreis schriftlich, bevor etwas beginnt: für eine Sitzung, eine Reihe davon oder einen Bau. Kein laufender Zähler.","Wir treffen uns per Video oder persönlich in Berlin. Alles, was wir einrichten, läuft in Ihren eigenen Konten und auf Ihren eigenen Geräten und bleibt Ihres."],staysTitle:"Was bei Ihnen bleibt.",stays:["Die Entscheidung. Wir legen die Optionen aus und was KI über jede davon herausfinden kann. Sie wählen.","Ihr Geld. Wir sind keine Finanz-, Rechts- oder Gesundheitsberater, und wir sagen es in dem Moment, in dem eine Frage in dieses Gebiet reicht.","Ihre Daten. Nichts von Ihnen liegt auf irgendetwas von uns.","Die Fähigkeit. Sie gehen so, dass Sie das nächste Mal ohne uns können, wenn Sie das wollen."],refuseTitle:"Was wir nicht tun werden.",refuse:["Ihnen sagen, welches Haus Sie kaufen, welche Anlage Sie wählen oder welchen Vertrag Sie unterschreiben sollen. Wir zeigen Ihnen, wie Sie schneller mehr herausfinden und wie Sie prüfen, was ein Modell Ihnen sagt, bevor Sie sich darauf verlassen.","Die Hausaufgaben eines Kindes machen oder ein Kind mit einem Chatbot allein lassen. Wir zeigen, wie er funktioniert, wo er sich irrt und wie man ihn gut nutzt — mit dem Erwachsenen im Raum.","Ihnen ein Abo, einen Kurs oder eine Plattform von uns verkaufen. Es gibt keine.","Eine Frage annehmen, bei der KI nichts beiträgt. Das hören Sie im Erstgespräch, kostenlos."]},principles:{title:"Drei Versprechen.",items:[{title:"Jede Entscheidung bleibt bei Ihnen.",text:"KI bereitet vor, entwirft, sortiert und schlägt vor. Die Entscheidung, die Diagnose, die Note, der Wert und das Urteil bleiben Ihre. Den Knopf, der sie Ihnen abnehmen würde, bauen wir nicht, und wir haben deswegen Aufträge abgelehnt."},{title:"Wir sagen laut Nein.",text:"Ist es zu wenig Arbeit, ist jeder Fall anders oder würde ein Kalender es lösen, hören Sie das statt eines Angebots. Das hat uns Projekte gekostet, und es ist der Hauptgrund, warum Mandanten uns anderen Inhabern empfehlen."},{title:"Nichts hängt an uns, was Ihr Team nicht selbst bedienen kann.",text:"Alles läuft in Ihren eigenen Konten, unter Ihren Zugängen, mit Ihren Schlüsseln. Jedes System bekommt eine schriftliche Übergabe und eine namentlich benannte Verantwortliche bei Ihnen, die vor dem Livegang schon selbst eine Regel darin geändert hat. Nichts braucht eine Lizenz, einen Server oder ein Abo von uns. Bleiben wir als Ihr Head of AI, dann weil es neues Terrain zu gewinnen gibt, nie weil ein Werkzeug ohne uns stehen bliebe."}]},about:{eyebrow:`Über ${e.brand}`,title:"Praktische KI, an Ihrer Seite.",text:[`${e.brand} ist ein Berliner Unternehmen, das Ihnen einen erfahrenen KI-Experten an die Seite stellt — Unternehmen, Teams und Forschungsgruppen jeder Größe und Branche ebenso wie einzelnen Menschen mit einer Entscheidung, einer Idee oder etwas zu lernen. Die meisten KI-Berater verkaufen Ihnen entweder eine Plattform oder automatisieren Ihren Papierkram. Wir tun etwas anderes. Wir sehen Ihre Lage so, wie eine neue Geschäftsführerin sie in ihrem ersten Monat sehen würde, fragen, was KI für Sie möglich macht, was vor einem Jahr noch nicht möglich war, und testen es mit Ihnen, bis wir es wissen. Die meisten, die mit KI bauen können, verstehen kein Geschäft, und die meisten, die ein Geschäft verstehen, können nicht bauen. Wir machen beides, und wir sagen Ihnen klar, wenn KI sich für Sie nicht rechnet.`,`${e.brand} gehört ${e.name} und wird von ihm geführt. Jahre professionelles Engineering hinter dem Unternehmen, im Bau von Produktions-KI-Systemen — der Art, auf die sich andere Menschen verlassen und die eine Prüfung, eine Übergabe und Kollegen übersteht, die nie nach dem Werkzeug gefragt haben. Genau das wendet ${e.brand} auf Häuser an, die klein genug für einen Raum und eine Entscheiderin sind: praktischer Rat in klarer Sprache, Werkzeuge, die für Ihren Betrieb gebaut sind und nicht für die Technik, und ein Inhaber, der vom ersten Gespräch bis zur Übergabe persönlich die Verantwortung für jedes Projekt trägt.`]},testimonials:{eyebrow:"Was Kunden sagen",note:""},faq:{eyebrow:"Häufige Fragen",title:"Häufige Fragen.",allLabel:"Alle Fragen",items:[{q:"Wer macht die Arbeit eigentlich?",a:`${e.brand} ist ein kleines Unternehmen, und sein Inhaber, ${e.name}, führt jeden Auftrag persönlich: Die Person, mit der Sie im Erstgespräch sprechen, ist die Person, die an Ihrem Tisch sitzt, die Werkzeuge einrichtet und die Schulung macht. Nichts wird an einen Junior weitergereicht. Dahinter: Jahre professionelles Engineering im Bau von Produktions-KI-Systemen, auf die sich andere Menschen verlassen.`},{q:"Ich bin eine Person, kein Unternehmen. Ist das etwas für mich?",a:"Ja, und die meisten Menschen, mit denen wir gearbeitet haben, kamen genau so, keiner davon zu der Zeit mit eigenem Unternehmen. Sie bringen eine Frage — eine Entscheidung, eine Idee, eine Gründung, etwas zu lernen, ein Kind, dem Sie etwas zeigen wollen — und bekommen eine Sitzung oder ein paar mit jemandem, der das beruflich macht, in klarer Sprache, zu einem Festpreis, der schriftlich vereinbart ist, bevor etwas beginnt. Das Erstgespräch ist so oder so kostenlos, und wenn KI bei Ihrer Frage nicht hilft, hören Sie das darin. Die Seite für Einzelpersonen beschreibt den Ablauf."},{q:"Sie haben eine Festanstellung. Wie geht das zusammen?",a:"Berechtigte Frage, und die Antwort liegt auf dem Tisch, bevor Sie sie stellen. Unser Inhaber hat eine Festanstellung im Bau von Produktions-KI, und aus dieser Rolle kommt der größte Teil der Produktionserfahrung hinter dieser Seite — sie ist der Grund, warum wir Ihnen sagen können, was eine Prüfung übersteht, statt es zu vermuten. Sie bedeutet auch, dass unsere Kapazität real begrenzt ist: Wir nehmen nur wenige Mandate gleichzeitig an, und die Form eines Mandats — welche Tage, vor Ort oder per Video, über wie viele Wochen — wird nach dem Erstgespräch schriftlich mit Ihnen vereinbart, bevor es einen Vertrag gibt. Wir werden Ihnen nie einen Tag zusagen und ihn dann verschieben. Wenn Sie mehr brauchen, als wir tragen können, hören Sie das, bevor Sie Geld ausgeben, nicht danach."},{q:"Sind unsere Daten bei Ihnen sicher?",a:"Ja, und bei regulierter Arbeit gestalten wir das zuerst, nicht zuletzt. Alles, was wir bauen, läuft in Ihren eigenen Konten, unter Ihren Zugängen, mit Ihren Schlüsseln — wir sind kein Hosting-Anbieter und halten keinen Zugang, den Sie nicht an einem Nachmittag entziehen können. Bevor wir etwas sehen: eine gegenseitige Verschwiegenheitserklärung, ein Auftragsverarbeitungsvertrag nach Art. 28 DSGVO und eine einseitige Vereinbarung darüber, auf welche Systeme wir Zugriff bekommen und für wie lange. Für Kanzleien zusätzlich eine gesonderte Verschwiegenheitsverpflichtung in Textform nach §43e BRAO mit ausdrücklicher Belehrung über die strafrechtlichen Folgen nach §203 StGB. Kein Training auf Ihren Inhalten, Namen entfernt, wo immer Daten Ihre Systeme verlassen müssen, und ein vollständiges Protokoll darüber, wer was getan hat. Wo ein Ablauf diese Bedingungen nicht erfüllen kann, wird er nicht gebaut. Die Sicherheitsseite führt das vollständig aus."},{q:"Was passiert, nachdem wir uns gemeldet haben?",a:"Wir sprechen dreißig Minuten, kostenlos, ohne Vorbereitung auf Ihrer Seite. Sie beschreiben Ihr Geschäft; wir sagen Ihnen ehrlich, wo KI für Sie etwas verändern könnte, wo nicht, und was es ungefähr bedeuten würde. Wenn es Sinn ergibt, bekommen Sie ein schriftliches Angebot für ein Angebot mit Festpreis. Wenn nicht, gehen Sie mit einer klaren Empfehlung — und das ist etwa jedes dritte Gespräch."},{q:"Können Sie die Rolle Head of AI für uns übernehmen?",a:"Ja, das ist die übliche Form. Nach der Beratung übernehmen wir die Rolle auf Pauschale: Richtung, Experimente, schriftliche Werkzeugentscheidungen, aktuell gehaltene KI-Regeln, Führungsbriefings und ein festes Zeitfenster pro Woche, auf das sich Ihr Team verlassen kann. Monatlich, und Sie können mit einem Monat Frist jederzeit aufhören. Niemand bei Ihnen braucht technisches Vorwissen: Sie erklären das Geschäft in Ihren Worten, alles Technische bleibt unser Problem."},{q:"Wir haben schon eine IT. Was machen Sie, was die nicht macht?",a:"Die IT hält die Systeme am Laufen. Wir stellen eine andere Frage: Was könnte dieses Unternehmen mit KI, was es heute nicht kann, und welche dieser Ideen überlebt einen echten Test? Dann führen wir die Tests mit Ihren Leuten durch. Die meisten IT-Teams sind froh, dass das endlich jemand tut. Wir arbeiten mit ihnen, nicht an ihnen vorbei — und wenn Ihre IT es selbst übernehmen will, umso besser: Wir verbringen die ersten Wochen mit ihnen, sie behalten die Systeme, und Sie zahlen uns kürzer."},{q:"Wir nutzen schon ChatGPT, oder wir haben Copilot. Wozu brauchen wir Sie?",a:"Gut — das heißt, Ihre Leute sind bereit. Es heißt meistens auch, dass Firmenmaterial in einem Werkzeug liegt, das niemand freigegeben hat, ohne Aufzeichnung darüber, was hineingegeben wurde. Eine Lizenz ist keine Fähigkeit. Copilot ist gut in dem Satz, der vor Ihnen steht; es sieht nicht, dass Ihre Verträge per E-Mail ankommen und verloren gehen, dass sieben Angebote normalisiert werden müssen, bevor man sie vergleichen kann, oder dass jede Frist Ihres Hauses in einem Dokument steht. Das sind keine Schreibprobleme. Wir arbeiten an der Form der Arbeit — und an den schriftlichen Regeln dafür, was überhaupt hineinkopiert werden darf."},{q:"Könnten wir nicht einfach einen KI-Ingenieur einstellen?",a:"Könnten Sie, und wenn Sie die Stelle schon beschreiben können, sollten Sie es wahrscheinlich tun. Die meisten Häuser können das an diesem Punkt noch nicht — und ein Ingenieur ohne Auftrag baut, was er interessant findet. Nehmen Sie zuerst die Beratung. Wenn die Antwort „stellen Sie jemanden ein“ lautet, sagen wir das, helfen bei der Stellenbeschreibung und verlieren die Pauschale gern."},{q:"Trifft das Werkzeug Entscheidungen für uns?",a:"Nein, und darauf ist alles ausgelegt. Der Rat bleibt beim Partner, der Wert bei der Maklerin, die Richtung beim Gründer, die Prioritäten bei der Bereichsleitung. Das Werkzeug übernimmt die Routinearbeit und bereitet das Material vor. Ihre Leute entscheiden. Den Knopf „Alle übernehmen“ haben wir mehr als einmal abgelehnt."},{q:"Sie haben noch nie in unserer Branche gearbeitet. Geht das trotzdem?",a:"Meistens ja. Ein Hersteller, eine Spedition, eine Privatklinik. In jedem Feld bisher lief das Mandat gleich ab: Wir lernen das Geschäft kennen, wir zeichnen auf, wo KI etwas Neues öffnet und wo sie aufhören muss, wir führen die ersten Experimente durch. Was wir bauen, ändert sich von Feld zu Feld vollständig. Wie wir es herausfinden, musste sich bisher nicht ändern — und sollte Ihre Branche die Ausnahme sein, hören Sie das früh und nicht am Ende."},{q:"Unsere Leute werden sich dagegen sperren.",a:"Manche schon, und meistens die, die recht damit haben. Widerstand ist fast immer eines von zwei Dingen: Angst um die Stelle, oder ein früheres Werkzeug, das die Arbeit schlechter gemacht hat. Deshalb bauen wir nur dort, wo die Person, die die Arbeit macht, sie selbst als Routine bezeichnet, wir bauen nie etwas, das über Einzelpersonen berichtet, und wir bauen den Knopf nicht, der die Entscheidung abnimmt. Das Beispiel zu Abteilungsleitungen auf dieser Seite ist ein System, das ordnet, was eine Führungskraft beobachtet hat, und ausdrücklich niemanden bewertet — die Variante, die Menschen überwacht, wurde zweimal angefragt und zweimal abgelehnt."},{q:"Wie würden wir den Nutzen belegen?",a:"Wir vereinbaren die Zahlen, bevor wir anfangen. Am Anfang schreiben wir zwei oder drei Messgrößen mit den heutigen Werten auf — Stunden für eine benannte Aufgabe, Tage von A nach B, die Anzahl der Sache, die immer schiefgeht. Am Ende messen wir dasselbe noch einmal an dem, was gebaut wurde. Haben sich die Werte nicht bewegt, steht das auch im Bericht. Und die ehrliche Rechnung ist einfach: die Aufgabe eine Woche mitzählen, mit dem multiplizieren, was eine Stunde dieser Person dem Haus wert ist, und dann halbieren. Ist die Zahl klein, sagen wir Ihnen, dass sich das nicht lohnt."},{q:"Sind wir dann von Ihnen abhängig?",a:"Nein, und das ist eingebaut statt versprochen. Alles läuft in Ihren Konten, unter Ihren Zugängen, mit Ihren API-Schlüsseln zum Selbstkostenpreis. Der Code liegt in Ihrem Repository. Jedes System hat eine schriftliche Übergabe und eine benannte Verantwortliche bei Ihnen, die schon selbst eine Regel darin geändert hat. Nichts braucht eine Lizenz, ein Konto, einen Server oder ein Abo von uns. Wären wir morgen verschwunden, liefe alles weiter — schreiben Sie es in den Vertrag, wir unterschreiben."},{q:"Was, wenn wir aufhören wollen?",a:"Die Pauschale endet mit einem Monat Frist, jeden Monat, ohne Begründung. Alles Gebaute läuft weiter: Ihre Konten, Ihre Zugänge, Ihr Repository, Ihre Schlüssel. Sie bekommen die Übergabe zu jedem System und auf Wunsch einen vollständigen Export der Protokolle sowie die schriftliche Bestätigung, dass wir nichts von Ihnen halten. Ein Beratung hat einen natürlichen Endpunkt eingebaut — danach entscheiden Sie, ob etwas weitergeht, und den Plan und die funktionierenden Systeme behalten Sie in jedem Fall."},{q:"Was, wenn KI für uns die falsche Antwort ist?",a:"Dann hören Sie das im Erstgespräch, bevor Sie sich zu etwas verpflichtet haben. Das kommt oft vor: Was nach einem KI-Problem aussieht, ist oft ein Ablauf, für den niemand zuständig ist, oder ein Werkzeug, das Ihr Team längst hat und nicht nutzt. Wir sagen das, und wir sagen es früh. Merken wir es erst im Haus, sagen wir es dann, hören auf und rechnen nur die bereits geleisteten Tage ab."},{q:"Müssen wir in Berlin sein?",a:"Nein. Das Erstgespräch ist ohnehin ein Telefonat oder Videocall, und die Rolle Head of AI läuft zum Teil per Video, sobald wir Ihr Unternehmen kennen. Bisherige Kunden sitzen auch in Leipzig und Brandenburg. Berlin macht nur den Teil vor Ort einfacher."},{q:"Wie viel Zeit kostet uns das?",a:"Das meiste liegt in der Beratung: Zeit mit uns im Haus, dazu ein Nachmittag Schulung für die Leute, die das Gebaute übernehmen. Danach kostet die Rolle Head of AI Ihre Führung ein kurzes Gespräch pro Woche und Ihr Team gelegentlich eine Stunde, um etwas Neues auszuprobieren. Was wir einrichten, kostet im Gebrauch Sekunden: neunzig Sekunden Diktat nach einem Ortstermin, ein Foto von einer Rechnung."}]},contactSection:{eyebrow:"Kontakt",title:"Erzählen Sie uns, womit Sie es zu tun haben.",lead:"Dreißig Minuten, kostenlos, ohne Vorbereitung. Wir sagen Ihnen ehrlich, wo KI für Sie etwas verändern könnte und wo nicht.",form:{name:"Name",email:"E-Mail",subject:"Worum geht es",subjects:["Unser Unternehmen oder Start-up","Unsere Forschungsgruppe oder unser Institut","Nur ich — eine persönliche Frage oder ein eigenes Projekt","Ein Vortrag oder ein Workshop","Etwas anderes"],message:"Nachricht",messageHint:"Ein Satz über Ihre Lage genügt. Keine Vorbereitung nötig.",emailHint:"Damit wir antworten können.",send:"Nachricht senden",sending:"Wird gesendet…",reply:"Wir antworten innerhalb eines Werktags.",success:"Vielen Dank. Wir melden uns innerhalb eines Werktags.",error:"Das hat nicht geklappt. Bitte schreiben Sie uns eine E-Mail.",note:"Lieber kein Formular? Buchen Sie ein Gespräch oder schreiben Sie uns direkt eine E-Mail."}},evidence:{eyebrow:"Nachweise",title:"Was wir tatsächlich gebaut haben.",items:[{name:"Ein Vertragssystem für eine Wirtschaftskanzlei",text:"Verträge werden beim Eingang abgelegt und versioniert, jede Frist steht im Kalender, und jeder eingehende Entwurf öffnet sich in Word mit Änderungsverfolgung, in der jeder Vorschlag seine Begründung mitbringt. Einen Knopf „Alle übernehmen“ gibt es nicht — wir wurden darum gebeten und haben abgelehnt.",link:"/work/lawyers/",linkLabel:"Den Fall lesen"},{name:"Eine Produktionsplattform für den Vertragslebenszyklus einer Konzern-Rechtsabteilung",text:"Dialogbasierte Erfassung, ein Copilot in der Anwendung und ein Microsoft-Word-Add-in, das echte Änderungsverfolgung erzeugt. Jede KI-Aktion läuft als der angemeldete Mensch, erbt also dieselben Berechtigungen und dasselbe Protokoll wie eine menschliche Anfrage, hinter einer Bestätigungsstufe, die jede Änderung zur Freigabe anhält. Sie hat einen kommerziellen Anbieter für rund 70.000 Euro im Jahr ersetzt. Gebaut von unserem Inhaber als interner KI-Ingenieur — die Arbeit, die uns gelehrt hat, was eine Prüfung übersteht.",link:"linkedin",linkLabel:"Der Nachweis auf LinkedIn"},{name:"Ein Kundenservice-Assistent, live in sechs Märkten",text:"Rund 45% der Erstkontakte werden ohne Menschen gelöst, mit versionierten Prompts und Modellkonfigurationen, sodass eine Änderung durch das Verschieben einer Kennzeichnung ausgeliefert wird und nicht durch ein neues Deployment. Ebenfalls interne Arbeit, in einem Berliner Unternehmen.",link:"linkedin",linkLabel:"Der Nachweis auf LinkedIn"},{name:"Mandatsarbeit in vielen Feldern",text:"Start-up-Gründer und Geschäftsführung, Bereichsleitungen in größeren Unternehmen, Forschungsgruppen, Architekturbüros, Marketingagenturen, eine Kanzlei, ein Immobilienunternehmen und ein Verein.",link:"/work/",linkLabel:"Alle Beispiele"}],note:"Wir sagen, was was ist. Die Mandate auf dieser Seite sind getrennt von den Systemen, die unser Inhaber als Angestellter gebaut hat, kein Mandantenmaterial hat je ein anderes Mandat berührt, und wir veröffentlichen keine Zahl, deren Herkunft wir nicht nennen können."},founder:{path:"/ueber-uns/",label:"Über uns",title:`Was hinter ${e.brand} steht`,metaDescription:`Professionelles Engineering hinter dem Unternehmen, im Bau von Produktions-KI-Systemen, auf die sich andere Menschen verlassen. Wen Sie tatsächlich beauftragen, wenn Sie ${e.brand} beauftragen.`,headline:"Was hinter Dinobridge steht.",intro:["Die meisten KI-Projekte scheitern aus einem von zwei Gründen. Entweder konnte die Person, die das Geschäft verstand, nicht bauen — dann löste das Gebaute das falsche Problem. Oder die Person, die bauen konnte, verstand das Geschäft nicht — dann löste es ein echtes Problem, das niemand hatte.",`Hinter ${e.brand} stehen Jahre professionelles Engineering, im Bau von Produktions-KI-Systemen: der Art, auf die sich andere Menschen verlassen und die eine Prüfung, eine Übergabe und Kollegen übersteht, die nie nach dem Werkzeug gefragt haben.`,`${e.brand} gehört ${e.name} und wird von ihm geführt. Diese Seite ist die Begründung, warum diese Kombination die Qualifikation ist und kein Kompromiss.`],whyTitle:"Warum diese Kombination die Qualifikation ist.",why:[{title:"KI-Entwicklung, nicht Prompt-Schreiben.",text:"Retrieval-Pipelines, Agenten, Modell- und Prompt-Versionierung, Deployment und Testgerüste, die entscheiden, was überhaupt in die Produktion darf. Das ist der Teil, der eine Demo von einem System unterscheidet, auf das sich Ihr Team verlassen kann, wenn niemand zusieht."},{title:"Betriebliche Erfahrung.",text:"Jahre davon in Organisationen, in denen die KI für Kollegen funktionieren musste, die nie danach gefragt hatten, eine Übergabe überstehen und einer Prüfung standhalten musste. Das ist eine andere Disziplin als etwas Beeindruckendes zu bauen, und sie entscheidet, ob ein System ein Jahr später noch benutzt wird."},{title:"Regulierte Abläufe.",text:"Verträge unter Verschwiegenheit, mit Berechtigungen und Protokoll als Anforderung erster Ordnung und nicht als späterer Bauabschnitt. Deshalb beginnt die Kanzleiarbeit mit dem, was das Haus nicht verlassen darf, und nicht mit dem, was das Modell kann."},{title:"Führung.",text:"Die Menschen, die diese Systeme beauftragt haben, waren die, die für den Bereich verantwortlich waren. Eine Abwägung in deren Vokabular zu erklären — und ein Nein zu hören und ein Nein zu sagen — ist der größte Teil der Arbeit."},{title:"Umsetzung.",text:"Jedes System, das auf dieser Seite beschrieben wird, hat die Person gebaut, die in dem Raum saß, in dem das Problem beschrieben wurde. Es gibt niemanden, an den man es weiterreichen könnte."}],honestTitle:"Der ehrliche Teil.",honestIntro:`${e.name} hat eine Festanstellung im Bau von Produktions-KI, und aus dieser Rolle kommt der größte Teil der Produktionserfahrung auf dieser Seite — sie ist der Grund, warum wir Ihnen sagen können, was eine Prüfung übersteht, statt es zu vermuten. Sie bedeutet auch, dass die Kapazität real begrenzt ist, und Sie sollten deren Form kennen, bevor wir sprechen, nicht danach.`,honest:["Wir nehmen nur wenige Mandate gleichzeitig an. Die Zeile oben auf der Startseite sagt, ob Platz ist.","Die Form eines Mandats — welche Tage, vor Ort oder per Video, über wie viele Wochen — wird nach dem Erstgespräch schriftlich mit Ihnen vereinbart, bevor es einen Vertrag gibt. Wir werden Ihnen nie einen Tag zusagen und ihn dann verschieben.","Die Rolle Head of AI ist ein festes Zeitfenster pro Woche, vorher vereinbart.","Mandatsarbeit und angestellte Arbeit bleiben streng getrennt. Kein Mandantenmaterial hat je ein anderes Mandat berührt, und keines wird es.","Wenn Sie mehr brauchen, hören Sie das, bevor es einen Vertrag gibt. Das ist vorgekommen."],refuseTitle:"Was wir nicht tun.",refuseText:"Den Knopf bauen, der die Entscheidung abnimmt. Etwas automatisieren, wo Ihr Name, Ihre Zulassung oder Ihre Unterschrift auf dem Ergebnis steht. Ihnen ein System verkaufen, wo ein Kalender, ein Formular oder eine gemeinsame Tabelle es löst — das hat uns Aufträge gekostet und ist der Hauptgrund, warum Mandanten uns anderen Inhabern empfehlen.",linkLabel:`${e.name} auf LinkedIn`},security:{path:"/sicherheit/",label:"Sicherheit",title:`Sicherheit und Verschwiegenheit — ${e.brand}`,metaDescription:`Was mit Ihren Daten passiert, wenn Sie mit ${e.brand} arbeiten: was wir vorher unterschreiben, wo verarbeitet wird, was bei Ihren Leuten bleibt, was wir nicht haben und was passiert, wenn wir aufhören.`,headline:"Sicherheit und Verschwiegenheit.",intro:[`${e.brand} ist ein kleines Unternehmen, dessen Arbeit bedeutet, Zugang zu Verträgen, Patientenakten, Handakten und Forschungsdaten anderer Menschen zu bekommen. Diese Seite ist die vollständige Antwort darauf, was damit passiert — geschrieben, bevor Sie gefragt haben.`,"Wenn etwas fehlt, das Sie brauchen: schreiben Sie uns. Wir beantworten Sicherheitsfragen schriftlich innerhalb von zwei Werktagen, wir füllen Ihren Fragebogen aus, und was wir nicht bejahen können, kreuzen wir als „nein“ an und nicht als „in Arbeit“."],approachTitle:"Unser Ansatz in drei Regeln.",approach:[{title:"Ihre Daten bleiben in Ihren Systemen.",text:"Alles, was wir bauen, läuft in Ihrer eigenen Umgebung, unter Ihren Konten, mit Ihren API-Schlüsseln, die direkt Ihnen abgerechnet werden. Wir sind kein Hosting-Anbieter und wollen keiner sein. Wir halten keinen Zugang, den Sie nicht an einem Nachmittag entziehen können."},{title:"Verschwiegenheit wird zuerst entworfen, nicht nachträglich ergänzt.",text:"Bei regulierter Arbeit — Patientenakten, Handakten, Kinderdaten, Forschung unter Ethikvotum — werden die Grenzen aufgeschrieben, bevor etwas entworfen wird. Manche Abläufe überleben das nicht. Die werden nicht gebaut, und wir sagen das, statt darum herumzuarbeiten."},{title:"Alles wird protokolliert.",text:"Wer was getan hat, an welchem Dokument, wann, und ob ein Mensch es angenommen oder abgelehnt hat. Ein System, das niemand prüfen kann, ist nicht einsatzfähig, egal was es sonst kann. Das entwerfen wir zuerst, nicht zuletzt."}],signTitle:"Was wir unterschreiben, bevor wir etwas von Ihnen sehen.",sign:["Eine gegenseitige Verschwiegenheitserklärung.","Einen Auftragsverarbeitungsvertrag nach Art. 28 DSGVO.","Eine einseitige Vereinbarung darüber, auf welche Systeme wir Zugriff bekommen und für wie lange. Den Zugriff erteilen Sie und entziehen Sie am Ende jedes Abschnitts; wir haben keine dauerhaften Administratorrechte.","Für Kanzleien eine gesonderte Verschwiegenheitsverpflichtung in Textform nach §43e BRAO, in der wir ausdrücklich über die strafrechtlichen Folgen einer Verletzung nach §203 StGB belehrt werden und in der festgelegt ist, ob weitere Personen hinzugezogen werden dürfen."],processingTitle:"Wo verarbeitet wird.",processing:["Mandantensysteme laufen in Ihrer eigenen Umgebung, in der Region, die Sie wählen.","Wo ein Dokument zum Lesen an ein Modell gehen muss, werden Anbieter, Region und Bedingungen im Angebot und im Auftragsverarbeitungsvertrag benannt, sodass Sie sie Ihrem eigenen Datenschutzbeauftragten vorlegen können, bevor etwas unterschrieben ist. Keine Verarbeitung außerhalb der EU. Würde ein Ablauf das verlangen, hören Sie das, bevor er entworfen wird — §43e BRAO verlangt bei Dienstleistungen im Ausland einen vergleichbaren Schutz, und der einfachste Weg dorthin ist, nicht ins Ausland zu gehen.","Kein Training auf Ihren Inhalten, und keine Speicherung beim Anbieter über die Anfrage hinaus.","Namen und Kennungen werden entfernt, wo Daten Ihre Systeme überhaupt verlassen müssen."],siteTitle:"Diese Website selbst.",siteText:"Statische Seiten, keine Cookies, keine Analyse, keine Nutzungsprofile, kein eigener Anwendungsserver. Die Seite liegt bei GitHub Pages (GitHub, Inc., USA) hinter Cloudflare (Cloudflare, Inc., USA); das Kontaktformular läuft über Formspree (USA) und der Buchungskalender über Cal.com (USA), der erst auf Ihren Klick lädt. Alle vier stehen in der Datenschutzerklärung. Sie verarbeiten Anfragen, keine Mandatsarbeit — kein Mandantenmaterial läuft über sie, und keiner von ihnen kommt in einem Mandat vor.",oversightTitle:"Menschliche Kontrolle.",oversightText:"Keine Entscheidung, Diagnose, Bewertung, Note, kein Urteil und keine Unterschrift entsteht in einem System, das wir bauen. Kein Ergebnis erreicht einen Mandanten, eine Gegenseite oder einen Patienten, ohne dass ein Mensch es angenommen hat. In nichts, was wir gebaut haben, gibt es einen Knopf „Alle übernehmen“; wir wurden darum gebeten und haben abgelehnt. Jede herausgezogene Angabe ist an die Seite und den Absatz geheftet, aus denen sie kommt, sodass die Prüfung Sekunden dauert, und das System gibt den genauen Wortlaut einer Norm oder Klausel zurück, statt sie umzuschreiben.",accessTitle:"Zugriffssteuerung.",accessText:"Die Systeme handeln als der angemeldete Mensch, eine KI-Aktion erbt also genau die Berechtigungen, die diese Person schon hat, und nie mehr. Wer eine Akte heute nicht öffnen kann, kann sie durch nichts, was wir bauen, morgen öffnen. Unser eigener Zugriff ist in der Vereinbarung benannt, auf die Arbeit begrenzt, von Ihnen erteilt und von Ihnen entzogen.",governanceTitle:"KI-Governance.",governanceText:"Jedes Mandat erzeugt schriftliche KI-Regeln für Ihr Haus: was KI hier darf und was nicht, wer entscheidet, was protokolliert wird und welche Werkzeuge freigegeben oder abgelehnt sind. Nach Artikel 4 der KI-Verordnung müssen Organisationen, die KI in der Arbeit einsetzen, die KI-Kompetenz der Menschen fördern, die sie nutzen; die nationalen Behörden haben die Aufsichtsbefugnisse seit dem 2. August 2026. Dieses Dokument und der Workshop dazu sind unser Beitrag dazu. Es ist keine Rechtsberatung, und wir hätten es lieber, wenn Ihre eigene Beratung es bestätigt.",handoverTitle:"Dokumentation, Ausstieg und Portabilität.",handoverText:"Eine schriftliche Übergabe für jedes System, erstellt in der Woche, in der es gebaut wird: was wo läuft, welcher Dienst was tut, wie man eine Regel ändert, wie man es abschaltet, was dann nicht mehr geht und worauf man schaut, wenn etwas seltsam aussieht. Geschrieben für die benannte Verantwortliche in Ihrem Team und geprüft, indem sie es benutzt, während wir zusehen. Beim Ausstieg: der Code liegt schon in Ihrem Repository, die Zugänge sind schon Ihre, die Daten liegen schon in Ihren Systemen, und auf Wunsch bekommen Sie einen vollständigen Export der Protokolle und die schriftliche Bestätigung, dass wir nichts von Ihnen halten. Nichts braucht eine Lizenz, ein Konto, einen Server oder ein Abo von uns.",notTitle:"Was wir nicht haben.",notText:"Wir sind nicht nach ISO 27001, SOC 2 oder TISAX zertifiziert. Wir haben kein Sicherheitsteam, kein 24/7-Monitoring und kein Penetrationstest-Programm. Wir sind ein erfahrener Ingenieur mit einer schriftlichen Arbeitsweise, ohne Angestellte und ohne Subunternehmer. Wenn Ihr Einkauf eine Zertifizierung oder einen Versicherungsnachweis verlangt, sind wir nicht der richtige Dienstleister, und Sie hören das im Erstgespräch und nicht in Woche sechs.",contactTitle:"Sicherheitsfragen.",contactText:"Schreiben Sie uns, wir antworten schriftlich innerhalb von zwei Werktagen. Schicken Sie Ihren Fragebogen, wir füllen ihn aus — und was wir nicht bejahen können, kreuzen wir als „nein“ an und nicht als „in Arbeit“."},marketingAgencies:{path:"/fuer-marketingagenturen/",label:"Für Marketingagenturen",title:`KI-Systeme für Marketingagenturen — ${e.brand}`,metaDescription:"KI-Beratung und Produktionssysteme für Marketingagenturen: Briefings, Recherche, Content-Abläufe und Reporting werden ruhiger und prüfbar, während Strategie und kreatives Urteil beim Team bleiben.",headline:"Mehr Raum für die Arbeit, die Kunden wirklich bemerken.",intro:["Eine Agentur braucht kein weiteres Chatfenster. Sie braucht einen verlässlichen Weg für alles, was in der Auslieferung auseinanderfällt: Briefings, Recherche, Quellen, Varianten, Freigaben und Reporting.","Wir finden die wiederholbare Arbeit rund um die kreative Entscheidung, bauen diesen Teil in Ihren eigenen Werkzeugen auf und lassen Strategie, Geschmack und Kundenbeziehung genau dort, wo sie hingehören: bei Ihrem Team."],imageAlt:"Ein abstrakter Kampagnenablauf, der verstreutes Ausgangsmaterial in ein klares freigegebenes Ergebnis verwandelt",imageCaption:"Von verstreuten Eingaben zu einem prüfbaren Kampagnensystem.",pressureTitle:"Wo Agenturzeit verschwindet.",pressureLead:"Der teure Teil ist selten die erste Idee. Es ist alles, was jedes Mal um sie herum passieren muss, ohne dass der Faden verloren geht.",pressures:[{title:"Das Briefing wechselt die Form.",text:"Calls, Decks, E-Mails und Kommentare werden zu einem Arbeitsbriefing, in dem offene Fragen vor Produktionsbeginn sichtbar sind."},{title:"Recherche wird wiederholt.",text:"Zielgruppen-, Wettbewerbs- und Marktmaterial wird mit Quellen gesammelt und bleibt für den nächsten Pitch nutzbar."},{title:"Versionen vermehren sich.",text:"Kanal- und Formatvarianten entstehen aus freigegebenem Ausgangstext, mit einer klaren Spur aller Änderungen und Freigaben."},{title:"Reporting beginnt bei null.",text:"Die wöchentlichen Nachweise werden laufend gesammelt, Ausreißer markiert, und das Team schreibt die Erklärung statt die Zahlen neu aufzubauen."}],systemTitle:"Eine ruhige Produktionslinie.",systemLead:"Das erste nützliche System ist meistens kleiner als eine „KI-Transformation“ und wertvoller als eine Sammlung von Prompts.",system:[{title:"Sammeln",text:"Briefing, Quelldateien, frühere Arbeiten und Kundenregeln kommen in einen nachvollziehbaren Eingang."},{title:"Strukturieren",text:"Fakten, Grenzen, Zielgruppen, Aussagen und fehlende Entscheidungen werden herausgezogen; jeder Fakt bleibt mit seiner Quelle verbunden."},{title:"Vorbereiten",text:"Rechercheübersichten, erste Entwürfe und Kanalvarianten entstehen nur innerhalb der vom Team freigegebenen Regeln."},{title:"Prüfen",text:"Jede wesentliche Änderung geht an eine benannte Person. Nichts wird von selbst veröffentlicht, versendet oder budgetiert."},{title:"Lernen",text:"Freigegebene Sprache, verworfene Richtungen und Kampagnennachweise bleiben für die nächste Arbeit verfügbar."}],boundaryTitle:"Die Grenze, die wir nicht überschreiten.",boundaryLead:"KI kann das Feld vorbereiten. Sie kann die Position nicht besitzen.",boundaries:["Keine erfundene Kundenerkenntnis, Leistungsbehauptung, Zitate oder Quellen.","Keine Veröffentlichung, Kundenantwort oder Budgetänderung ohne benannte menschliche Freigabe.","Kein System, das einzelne Kreative bewertet oder Aktivität überwacht.","Kein Modell, das mit vertraulichem Material eines Kunden für einen anderen Kunden trainiert wird.","Strategie, Geschmack, Verantwortung und Kundenbeziehung bleiben bei Ihren Leuten."],startTitle:"Gute Ausgangspunkte.",startLead:"Nehmen Sie eine wiederkehrende Übergabe mit sichtbaren Kosten. Wir zeichnen sie auf, testen sie an jüngster Arbeit und messen vorher und nachher dasselbe.",starts:[{title:"Briefing-Eingang",text:"Aus gemischtem Kundenmaterial werden ein vollständiges Arbeitsbriefing und eine Liste offener Entscheidungen."},{title:"Recherche-Desk",text:"Quellenbasierte Markt- und Wettbewerbsbeobachtung, die zwischen Pitches aktuell bleibt."},{title:"Content Operations",text:"Freigegebener Ausgangstext wird in Kanalvarianten, Prüfung und Versionshistorie geführt."},{title:"Kundenreporting",text:"Nachweise werden planmäßig gesammelt und Ausnahmen für die Einordnung durch eine Strategin markiert."}],ctaTitle:"Bringen Sie uns eine chaotische Übergabe.",ctaText:"Dreißig Minuten, kostenlos, ohne Deck. Zeigen Sie uns, wo die Arbeit stockt; wir sagen Ihnen, ob KI etwas ändert, was menschlich bleiben muss und wie ein sinnvoller erster Test aussieht."},lawFirms:{path:"/fuer-kanzleien/",label:"Für Kanzleien",title:`KI in der Kanzlei, ohne juristisches Urteil anzutasten — ${e.brand}`,metaDescription:"Für geschäftsführende Partner, Boutiquen und Rechtsabteilungen: was KI sicher übernehmen kann, was anwaltlich kontrolliert bleibt, wie Verschwiegenheit nach §43e BRAO und §203 StGB geschützt wird und was mit Mandantendaten passiert.",headline:"KI in der Kanzlei, ohne einen einzigen Punkt juristischen Urteils anzutasten.",intro:["Für geschäftsführende Partner, Wirtschaftskanzleien, Boutiquen und Rechtsabteilungen. Ihr Papierkram wird schneller. Ihr Rat, Ihre Zugeständnisse und Ihre Unterschrift bewegen sich um keinen Millimeter.","Ihr Ruf und Ihre Berufspflichten stehen auf dem Spiel, nicht unsere. Deshalb beantwortet diese Seite die Fragen, die Sie uns stellen müssten, in der Reihenfolge, in der Sie sie stellen würden."],sections:[{title:"Warum wir",text:["Die Person, die in Ihrer Kanzlei arbeiten würde, hat das schon gebaut, in Produktion, als interner Ingenieur: eine durchgängige Plattform für den Vertragslebenszyklus einer Konzern-Rechtsabteilung — dialogbasierte Erfassung, ein Copilot in der Anwendung und ein Microsoft-Word-Add-in, das echte Änderungsverfolgung erzeugt. Jede KI-Aktion darin lief als der angemeldete Mensch, erbte also dieselben Berechtigungen und dasselbe Protokoll wie eine menschliche Anfrage, hinter einer Bestätigungsstufe, die jede Änderung zur Freigabe anhielt. Sie hat einen kommerziellen Anbieter für rund 70.000 Euro im Jahr ersetzt.","Das ist der Unterschied zwischen einem Berater, der über Legal AI gelesen hat, und einem Ingenieur, der sie in einer Rechtsabteilung mit Protokoll ausgeliefert hat. Und es ist der Grund, warum unsere erste Frage zu jedem Ablauf „Wer hat das getan, und können Sie es zeigen?“ lautet und nicht, was das Modell kann."]},{title:"Was KI sicher übernehmen kann",lead:"Verträge als Gegenstände. Nicht Recht.",list:["Verträge aus dem Postfach ziehen, sobald sie ankommen","Jede Datei dauerhaft nach einer Konvention benennen und versionieren, mit erhaltener Historie","Parteien, Daten, Laufzeit, Kündigungsfristen, Rechtswahl, Haftungsgrenzen und automatische Verlängerung herausziehen — jedes Feld an Seite und Absatz geheftet, aus denen es kommt","Der Fristenkalender: jedes Datum aus jedem Vertrag, vor Ihnen, bevor es zählt","Einen eingehenden Entwurf gegen Ihr eigenes Playbook halten und markieren, wo er abweicht","Ein Erstmarkup in Word mit Änderungsverfolgung, jeder Vorschlag mit seiner Begründung","Die Gegenseite nachfassen, die den Entwurf nicht zurückgeschickt hat, und die interne Zeichnungsberechtigte","Korrekt in Ihr Dokumentensystem ablegen, beim ersten Mal","„Wo ist dieser Vertrag, und welche Version gilt?“ sofort beantworten"],text:["Das Versionsproblem ist in den ersten Wochen weg, und das ist die Änderung, die man zuerst merkt."]},{title:"Was dauerhaft anwaltlich kontrolliert bleibt",text:["Ob eine Klausel akzeptabel ist. Was man zugesteht. Beratung, an wen auch immer, intern wie extern. Die Unterschrift.","Es wird keine Beratung erzeugt. Es geht nie etwas automatisch an die Gegenseite. Keine Klausel wird ohne genannte Begründung umformuliert, die Sie bewerten können. Es gibt keinen Knopf „Alle übernehmen“ — wir wurden gebeten, ihn zu bauen, und haben abgelehnt, und der Partner, der gefragt hat, sagt heute, er hätte nicht weitergearbeitet, wenn wir ihn gebaut hätten.","Jeder Vorschlag wird einzeln von einer Anwältin angenommen oder abgelehnt, in Word — Ihrem Werkzeug, nicht unserem."]},{title:"Wie Verschwiegenheit geschützt wird",lead:"Zwei Instrumente, weil das deutsche Berufsrecht beide verlangt und nur eines davon Datenschutz ist.",list:["Ein Auftragsverarbeitungsvertrag (AVV) nach Art. 28 DSGVO, unterschrieben, bevor wir etwas sehen.","Eine Verschwiegenheitsverpflichtung in Textform nach §43e BRAO, in der wir ausdrücklich über die strafrechtlichen Folgen einer Verletzung nach §203 StGB belehrt werden und in der festgelegt ist, ob weitere Personen hinzugezogen werden dürfen — die Antwort ist nein, weil Dinobridge eine Person ohne Angestellte und ohne Subunternehmer ist. Ändert sich das je, ändert es sich vorher durch schriftliche Ergänzung, nicht danach."],text:["Wir wissen, dass §43e eine andere Pflicht ist als Art. 28, und wir wissen, dass Sie dokumentieren müssen, den Dienstleister sorgfältig ausgewählt zu haben. Wir geben Ihnen die Unterlagen dafür, am Anfang, ohne dass Sie danach fragen müssen."]},{title:"Was mit Mandantendaten passiert",text:["Sie bleiben in Ihren Systemen. Jedes System, das wir bauen, läuft in Ihrer Umgebung, unter Ihren Konten, mit Ihren API-Schlüsseln, die direkt Ihnen abgerechnet werden. Wir hosten keine Akteninhalte, wir kopieren sie nicht auf eigene Infrastruktur, und wir halten keinen Zugang, den Sie nicht heute Nachmittag entziehen können.","Wo ein Dokument zum Lesen an ein Modell gehen muss, werden Anbieter, Region und Bedingungen im Angebot und im AVV benannt, sodass Sie sie Ihrem eigenen Datenschutzbeauftragten vorlegen können, bevor etwas unterschrieben ist. Kein Training auf Ihren Inhalten und keine Speicherung über die Anfrage hinaus. Keine Verarbeitung außerhalb der EU — und würde ein Ablauf das verlangen, hören Sie das, bevor er entworfen wird, weil §43e bei Dienstleistungen im Ausland einen vergleichbaren Schutz verlangt und der einfachste Weg dorthin ist, nicht ins Ausland zu gehen.","Wo ein Ablauf diese Bedingungen nicht erfüllen kann, wird er nicht gebaut. Das ist vorgekommen, und wir haben es gesagt, statt darum herumzuarbeiten."]},{title:"Was protokolliert wird, und wer was sehen kann",text:["Jede Aktion: wer sie ausgelöst hat, an welchem Dokument, wann, was zurückkam, und ob ein Mensch sie angenommen oder abgelehnt hat. Aufbewahrt für einen mit Ihnen vereinbarten Zeitraum, dann planmäßig gelöscht, und jederzeit vollständig von Ihnen exportierbar, ohne uns zu fragen. Ein juristisches KI-System ohne Protokoll ist nicht einsatzfähig, egal was es sonst kann.","Der Zugriff folgt Ihren bestehenden Berechtigungen. Die Systeme handeln als der angemeldete Mensch, eine KI-Aktion erbt also genau die Rechte, die diese Person schon hat, und nie mehr — wer eine Akte heute nicht öffnen kann, kann sie durch nichts, was wir bauen, morgen öffnen. Unser eigener Zugriff ist in der Vereinbarung benannt, auf die Arbeit begrenzt, von Ihnen erteilt und am Ende jedes Abschnitts von Ihnen entzogen. Dauerhafte Administratorrechte haben wir nicht."]},{title:"Wie ein Vertrag tatsächlich geprüft wird",steps:["Er kommt an. Er wird erkannt, versioniert, mit seinem Mandat und seiner Vorversion verknüpft und abgelegt.","Das Übersichtsblatt entsteht, jedes Feld an seine Fundstelle geheftet.","Er wird gegen Ihr Playbook gehalten — Ihre eigenen schriftlichen Positionen — und die Abweichungen werden markiert.","Ein Word-Dokument mit Änderungsverfolgung entsteht, jeder Vorschlag mit seiner Begründung als Kommentar: aus welcher Playbook-Position er kommt oder welches Risiko er adressiert.","Eine Anwältin öffnet es in Word und nimmt jede Änderung einzeln an oder lehnt sie ab.","Jede dieser Entscheidungen wird protokolliert."],text:["Zwischen dem ersten und dem fünften Schritt verlässt nichts die Kanzlei, und nach dem fünften passiert nichts ohne einen Menschen."]},{title:"Wie das Halluzinationsrisiko begrenzt wird",lead:"Vier Mechanismen, und keiner davon ist „wir nehmen ein gutes Modell“.",list:["Nichts wird ohne Fundstelle behauptet. Jede herausgezogene Angabe ist an Seite und Absatz geheftet, die Prüfung dauert vier Sekunden. Eine Angabe, die man nicht prüfen kann, ist schlimmer als keine — sie sieht wie Wissen aus.","Nichts wird ohne Begründung vorgeschlagen. Ein Markup ohne genannte Grundlage ist nicht prüfbar, also kann das System keines erzeugen.","Verglichen wird gegen Ihr eigenes schriftliches Playbook, nicht gegen die Vorstellung eines Modells von Marktstandard. Steht eine Position nicht schriftlich fest, hat das System nichts zum Vergleichen und sagt das.","Das System umschreibt nie. Bei Normen und Klauseln gibt es den genauen Wortlaut mit Fundstelle zurück, denn eine umformulierte Vorschrift ist ein Haftungsrisiko."],text:["Und strukturell: Es gibt keinen Weg vom System zu einer Gegenseite, einer Mandantin oder einem internen Empfänger, der nicht über einen Menschen führt, der eine konkrete Änderung annimmt."]},{title:"Der Einführungsweg, und was es anbindet",text:["Vor allem anderen: die Verschwiegenheitserklärung, der AVV, die §43e-Verpflichtung und eine einseitige Vereinbarung darüber, auf welche Systeme wir zugreifen und für wie lange.","Dann zuerst Eingang und Ablage — nichts Intelligentes. Dann das Übersichtsblatt und der Fristenkalender, beide innerhalb von Tagen nützlich, und der Kalender ist das Stück mit dem höchsten Rohwert, weil eine versäumte Kündigungsfrist ein Schaden ist. Dann das Playbook: Ihre Positionen, richtig aufgeschrieben, mit Ihnen. Das ist der schwerste und wertvollste Teil des Projekts, und der, den die meisten Kanzleien nie gemacht haben. Das Erstmarkup kommt zuletzt, weil das Playbook zuerst existieren muss und das Playbook Ihre Arbeit ist, nicht unsere. Wer Ihnen ein Markup in der zweiten Woche verspricht, hat noch nie ein Playbook mit einer Kanzlei geschrieben.","Es arbeitet mit Outlook und Exchange, mit Word als nativem Add-in, damit Ihre Leute in Word bleiben statt in irgendeinem Portal, mit SharePoint und Windows-Freigaben, mit Ihrem Kalender für den Fristenkalender und mit Ihrem Dokumentenmanagement, wo es eine Schnittstelle hat. Hat Ihres keine, hören Sie das im Erstgespräch und nicht in der dritten Woche."]},{title:"Wie schnell Sie etwas davon haben",text:["Ablage und Versionierung zuerst, und das ist die Änderung, die zuerst genannt wird. Dann der Fristenkalender, und der verhindert Schäden. Das Markup zuletzt, sobald das Playbook steht.","Durchgehend gilt: Für jedes Stück ist eine Person in Ihrer Kanzlei benannt, darin geschult, und sie hat vor dem Livegang selbst eine Regel darin geändert."]},{title:"Welche Nachweise es gibt",text:["Eine Wirtschaftskanzlei mit zwei Partnern und eine Rechtsabteilung von fünf Personen in einem Industriekonzern mit rund dreihundert Mitarbeitenden. Beide wollten nicht genannt werden — nur Rolle und Region, was in diesem Bereich die Regel ist — und beide haben zugesagt, nach einem Erstgespräch mit einem ernsthaften Interessenten zu sprechen. Wir führen privat Buch darüber, wer was gesagt hat.","Und davon unabhängig, ohne die Erlaubnis eines Mandanten prüfbar: die Produktionsplattform für den Vertragslebenszyklus, oben auf dieser Seite beschrieben, intern gebaut, die einen Anbieter für rund 70.000 Euro im Jahr ersetzt hat."]},{title:"Was passiert, wenn Sie nicht mehr mit uns arbeiten",text:["Alles läuft weiter. Es liegt in Ihrer Umgebung, unter Ihren Konten, mit Ihren Schlüsseln, und der Code liegt in Ihrem Repository. Sie bekommen für jedes System eine schriftliche Übergabe — erstellt in der Woche, in der es gebaut wurde, nicht in der Woche, in der wir gehen — mit dem, was wo läuft, wie man eine Regel ändert, wie man es abschaltet und was dann nicht mehr geht. Eine benannte Person in Ihrer Kanzlei hat es schon benutzt, während wir zusahen.","Auf Wunsch, jederzeit: ein vollständiger Export aller Protokolle und die schriftliche Bestätigung, dass wir nichts von Ihnen halten. Nichts braucht eine Lizenz, ein Konto oder ein Abo von uns. Wären wir morgen verschwunden, liefen Ihre Systeme, und Ihre Leute könnten sie ändern."]},{title:"Wo wir Nein sagen",text:["Maßgeschneiderte, hochwertige Einzelverhandlungen. Dort gibt es kein Playbook, weil es keine Wiederholung gibt, und ein Erstmarkup auf einem wirklich neuen Deal ist Rauschen im Gewand von Hilfe.","Alles, was Beratung erzeugt. Alles, was versendet. Alles mit einem Knopf „Alle übernehmen“."]}],ctaTitle:"Einen Ablauf gemeinsam durchsprechen.",ctaText:"Dreißig Minuten, kostenlos, ohne Vorbereitung. Wenn die Rahmenbedingungen Ihrer Kanzlei das undurchführbar machen, hören Sie das im Gespräch und nicht in einem Angebot.",disclaimer:"Nichts auf dieser Seite ist Rechtsberatung, und wir sind keine Anwälte. §43e BRAO und §203 StGB sind genannt, weil sie regeln, wie Sie uns beauftragen dürfen; lassen Sie unsere Verpflichtung bitte von Ihrer eigenen berufsrechtlichen Beratung prüfen, bevor Sie sie unterschreiben."},footer:{impressum:"Impressum",datenschutz:"Datenschutz"}};export{i as d};
